import React from 'react';
import SEOHead from '@/components/SEO/SEOHead';

interface CategoryPageSEOProps {
  categoryName: string;
  categorySlug: string;
  categoryDescription?: string;
  announcementCount?: number;
}

export function CategoryPageSEO({ 
  categoryName, 
  categorySlug, 
  categoryDescription,
  announcementCount
}: CategoryPageSEOProps) {
  const title = `Annonces ${categoryName} en Alg├®rie | Aladdin Annonces`;
  const description = categoryDescription || 
    `Trouvez les meilleures annonces ${categoryName.toLowerCase()} en Alg├®rie. ${
      announcementCount ? `${announcementCount} annonces disponibles. ` : ''
    }Publiez et consultez des milliers d'annonces gratuites!`;
  
  return (
    <>
      <SEOHead 
        title={`Annonces ${categoryName}`}
        description={description}
        category={categoryName}
        image={`/images/categories/${categorySlug}.jpg`}
        url={`/fr/category/${categorySlug}`}
        breadcrumbs={[
          { label: 'Accueil', href: '/fr' },
          { label: categoryName, href: `/fr/category/${categorySlug}` }
        ]}
      />
    </>
  );
}

export default CategoryPageSEO;

import React from 'react';
import SEOHead from '@/components/SEO/SEOHead';

interface SubcategoryPageSEOProps {
  categoryName: string;
  categorySlug: string;
  subcategoryName: string;
  subcategorySlug: string;
  announcementCount?: number;
}

export function SubcategoryPageSEO({ 
  categoryName, 
  categorySlug, 
  subcategoryName, 
  subcategorySlug,
  announcementCount
}: SubcategoryPageSEOProps) {
  const title = `Annonces ${subcategoryName} ${categoryName} en Alg├®rie | Aladdin Annonces`;
  const description = 
    `Trouvez les meilleures annonces ${subcategoryName.toLowerCase()} en ${categoryName.toLowerCase()} en Alg├®rie. ${
      announcementCount ? `${announcementCount} annonces disponibles. ` : ''
    }Publiez et consultez des milliers d'annonces gratuites!`;
  
  return (
    <>
      <SEOHead 
        title={`Annonces ${subcategoryName} ${categoryName}`}
        description={description}
        category={categoryName}
        subcategory={subcategoryName}
        image={`/images/subcategories/${subcategorySlug}.jpg`}
        url={`/fr/category/${categorySlug}/${subcategorySlug}`}
        breadcrumbs={[
          { label: 'Accueil', href: '/fr' },
          { label: categoryName, href: `/fr/category/${categorySlug}` },
          { label: subcategoryName, href: `/fr/category/${categorySlug}/${subcategorySlug}` }
        ]}
      />
    </>
  );
}

export default SubcategoryPageSEO;

import { useCallback, useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Plus, FolderTree, Eye, Settings, Database } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import CategoryEditor from "./CategoryEditor";
import CategoryTreeView from "./CategoryTreeView";
import CategoryBulkActions from "./CategoryBulkActions";
import { toast } from "@/components/ui/use-toast";
import { MenuCategory } from "@/data/categoryTypes";
import { supabase } from "@/integrations/supabase/client";
import { logger } from "@/utils/silentLogger";
import { mergeOfficialAndSupabaseCategories, useCategories, useInvalidateCategories } from "@/services/supabaseCategoriesService";

interface CategoryData {
  id: string;
  name: string;
  slug: string;
  description?: string;
  parentId?: string;
  children: CategoryData[];
  isActive: boolean;
  sortOrder: number;
  announcementCount: number;
  seoTitle?: string;
  seoDescription?: string;
  metaTags?: string[];
}

const CategoryManagement = () => {
  const [categories, setCategories] = useState<CategoryData[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [maxDepth, setMaxDepth] = useState(3);
  const [maxCategoriesPerLevel, setMaxCategoriesPerLevel] = useState(50);
  const [autoSlug, setAutoSlug] = useState(true);
  const [autoValidation, setAutoValidation] = useState(true);
  const [autoSave, setAutoSave] = useState(false);
  const [totalAnnouncementsExact, setTotalAnnouncementsExact] = useState(0);

  const [editingCategory, setEditingCategory] = useState<CategoryData | null>(null);
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [selectedTab, setSelectedTab] = useState("list");
  const [isSaving, setIsSaving] = useState(false);
  const { data: categoriesFromSupabase = [] } = useCategories('fr');
  const invalidateCategories = useInvalidateCategories();

  const isUUID = (value?: string) =>
    typeof value === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);

  const buildTreeFromMenu = (
    items: Array<{ name: string; slug: string; subcategories?: Array<{ name: string; slug: string; subcategories?: unknown[] }> }>,
    parentPath: string | undefined,
    isRoot: boolean,
    rootCounts: Map<string, number>,
    subCounts: Map<string, number>
  ): CategoryData[] => {
    return items.map((item, index) => {
      const nodeId = typeof (item as { id?: unknown }).id === "string" && (item as { id?: string }).id
        ? (item as { id: string }).id
        : (parentPath ? `${parentPath}/${item.slug}` : item.slug);
      const children = buildTreeFromMenu(
        (item.subcategories || []) as Array<{ name: string; slug: string; subcategories?: Array<{ name: string; slug: string; subcategories?: unknown[] }> }>,
        nodeId,
        false,
        rootCounts,
        subCounts
      );

      return {
        id: nodeId,
        name: item.name,
        slug: item.slug,
        description: undefined,
        parentId: parentPath,
        children,
        isActive: true,
        sortOrder: index + 1,
        announcementCount: isRoot ? (rootCounts.get(item.slug) || 0) : (subCounts.get(item.slug) || 0),
      };
    });
  };

  const loadCategories = useCallback(async () => {
      setIsLoading(true);
      try {
        const menu = mergeOfficialAndSupabaseCategories('fr', categoriesFromSupabase as MenuCategory[]);

        const [announcementTotalRes, rootCategoryCountRes, subCategoryCountRes] = await Promise.all([
          supabase.from('announcements_public').select('id', { count: 'exact', head: true }).eq('status', 'active'),
          supabase
            .from('announcements_public')
            .select('category_slug, count:id')
            .eq('status', 'active'),
          supabase
            .from('announcements_public')
            .select('subcategory_id, count:id')
            .eq('status', 'active')
            .not('subcategory_id', 'is', null),
        ]);

        const rootCounts = new Map<string, number>();
        const subCounts = new Map<string, number>();

        const rootRows = (rootCategoryCountRes?.data || []) as Array<{ category_slug?: string; count?: number }>;
        rootRows.forEach((row) => {
          if (typeof row?.category_slug === 'string') {
            rootCounts.set(row.category_slug, Number(row.count || 0));
          }
        });

        const subRows = (subCategoryCountRes?.data || []) as Array<{ subcategory_id?: string; count?: number }>;
        subRows.forEach((row) => {
          if (typeof row?.subcategory_id === 'string') {
            subCounts.set(row.subcategory_id, Number(row.count || 0));
          }
        });

        const tree = buildTreeFromMenu(
          menu as Array<{ name: string; slug: string; subcategories?: Array<{ name: string; slug: string; subcategories?: unknown[] }> }>,
          undefined,
          true,
          rootCounts,
          subCounts
        );
        setCategories(tree);
        setTotalAnnouncementsExact(announcementTotalRes.count || 0);
      } catch (error) {
        logger.error('Erreur chargement cat├®gories admin:', error);
        toast({
          title: "Erreur de chargement",
          description: "Impossible de charger les cat├®gories officielles",
          variant: "destructive",
        });
      } finally {
        setIsLoading(false);
      }
    }, [categoriesFromSupabase]);

  useEffect(() => {
    void loadCategories();
  }, [loadCategories]);

  const handleSaveCategory = async (categoryData: Partial<CategoryData>) => {
    const parentId = categoryData.parentId && String(categoryData.parentId).trim() ? String(categoryData.parentId) : null;
    if (parentId && !isUUID(parentId)) {
      toast({
        title: "Cat├®gorie parente invalide",
        description: "S├®lectionnez une cat├®gorie parente synchronis├®e avec la base",
        variant: "destructive",
      });
      return;
    }

    setIsSaving(true);
    try {
      if (editingCategory) {
        if (!isUUID(editingCategory.id)) {
          toast({
            title: "Modification non autoris├®e",
            description: "Cette cat├®gorie locale n'est pas encore synchronis├®e en base",
            variant: "destructive",
          });
          return;
        }

        const { error } = await supabase
          .from("categories")
          .update({
            name: categoryData.name || editingCategory.name,
            slug: categoryData.slug || editingCategory.slug,
            description: categoryData.description ?? editingCategory.description ?? null,
            parent_id: parentId,
            position_order: Number(categoryData.sortOrder ?? editingCategory.sortOrder ?? 0),
            is_active: categoryData.isActive ?? editingCategory.isActive,
            icon: categoryData.icon ?? null,
          } as Record<string, unknown>)
          .eq("id", editingCategory.id);

        if (error) throw error;

        toast({
          title: "Cat├®gorie mise ├á jour",
          description: `La cat├®gorie "${categoryData.name || editingCategory.name}" a ├®t├® mise ├á jour`,
        });
      } else {
        const insertPayload = {
          id: crypto.randomUUID(),
          name: categoryData.name || "",
          slug: categoryData.slug || "",
          description: categoryData.description ?? null,
          parent_id: parentId,
          position_order: Number(categoryData.sortOrder ?? 0),
          is_active: categoryData.isActive ?? true,
        };

        const { error } = await supabase.from("categories").insert(insertPayload as Record<string, unknown>);
        if (error) throw error;

        toast({
          title: "Cat├®gorie cr├®├®e",
          description: `La cat├®gorie "${categoryData.name}" a ├®t├® cr├®├®e avec succ├¿s`,
        });
      }

      invalidateCategories("fr");
      await loadCategories();
      setIsEditorOpen(false);
      setEditingCategory(null);
    } catch (error) {
      logger.error("Erreur sauvegarde cat├®gorie:", error);
      toast({
        title: "Erreur",
        description: "Impossible d'enregistrer la cat├®gorie",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleEditCategory = (category: CategoryData) => {
    setEditingCategory(category);
    setIsEditorOpen(true);
  };

  const handleDeleteCategory = async (categoryId: string) => {
    if (!isUUID(categoryId)) {
      toast({
        title: "Suppression non autoris├®e",
        description: "Cette cat├®gorie locale n'est pas encore synchronis├®e en base",
        variant: "destructive",
      });
      return;
    }

    setIsSaving(true);
    try {
      const { error } = await supabase.from("categories").delete().eq("id", categoryId);

      if (error) {
        const { error: archiveError } = await supabase
          .from("categories")
          .update({ is_active: false } as Record<string, unknown>)
          .eq("id", categoryId);
        if (archiveError) throw archiveError;
        toast({
          title: "Cat├®gorie d├®sactiv├®e",
          description: "Suppression impossible (relations existantes), cat├®gorie archiv├®e",
        });
      } else {
        toast({
          title: "Cat├®gorie supprim├®e",
          description: "La cat├®gorie a ├®t├® supprim├®e avec succ├¿s",
        });
      }

      invalidateCategories("fr");
      await loadCategories();
    } catch (error) {
      logger.error("Erreur suppression cat├®gorie:", error);
      toast({
        title: "Erreur",
        description: "Impossible de supprimer la cat├®gorie",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleToggleStatus = async (categoryId: string, isActive: boolean) => {
    if (!isUUID(categoryId)) {
      toast({
        title: "Action non autoris├®e",
        description: "Cette cat├®gorie locale n'est pas encore synchronis├®e en base",
        variant: "destructive",
      });
      return;
    }

    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("categories")
        .update({ is_active: isActive } as Record<string, unknown>)
        .eq("id", categoryId);
      if (error) throw error;

      toast({
        title: isActive ? "Cat├®gorie activ├®e" : "Cat├®gorie d├®sactiv├®e",
        description: "Le statut de la cat├®gorie a ├®t├® mis ├á jour",
      });

      invalidateCategories("fr");
      await loadCategories();
    } catch (error) {
      logger.error("Erreur changement statut cat├®gorie:", error);
      toast({
        title: "Erreur",
        description: "Impossible de mettre ├á jour le statut",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const removeCategoryById = (items: CategoryData[], categoryId: string): { tree: CategoryData[]; removed: CategoryData | null } => {
    let removed: CategoryData | null = null;

    const next = items
      .map((item) => {
        if (item.id === categoryId) {
          removed = item;
          return null;
        }
        if (item.children.length === 0) return item;
        const childResult = removeCategoryById(item.children, categoryId);
        if (childResult.removed) removed = childResult.removed;
        return { ...item, children: childResult.tree };
      })
      .filter(Boolean) as CategoryData[];

    return { tree: next, removed };
  };

  const handleMoveCategory = async (categoryId: string, newParentId?: string) => {
    if (newParentId && newParentId === categoryId) {
      toast({
        title: "D├®placement invalide",
        description: "Une cat├®gorie ne peut pas ├¬tre d├®plac├®e dans sa propre sous-cat├®gorie",
        variant: "destructive",
      });
      return;
    }

    if (!isUUID(categoryId)) {
      toast({
        title: "Action non autoris├®e",
        description: "Cette cat├®gorie locale n'est pas encore synchronis├®e en base",
        variant: "destructive",
      });
      return;
    }
    if (newParentId && !isUUID(newParentId)) {
      toast({
        title: "Parent invalide",
        description: "Le parent s├®lectionn├® doit ├¬tre synchronis├® en base",
        variant: "destructive",
      });
      return;
    }

    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("categories")
        .update({ parent_id: newParentId || null } as Record<string, unknown>)
        .eq("id", categoryId);
      if (error) throw error;

      toast({
        title: "Cat├®gorie d├®plac├®e",
        description: "La hi├®rarchie a ├®t├® mise ├á jour",
      });

      invalidateCategories("fr");
      await loadCategories();
    } catch (error) {
      logger.error("Erreur d├®placement cat├®gorie:", error);
      toast({
        title: "Erreur",
        description: "Impossible de d├®placer la cat├®gorie",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  // Fonctions utilitaires pour manipuler l'arbre de cat├®gories
  const updateCategoryInTree = (categories: CategoryData[], categoryId: string, updates: Partial<CategoryData>): CategoryData[] => {
    return categories.map(category => {
      if (category.id === categoryId) {
        return { ...category, ...updates };
      }
      if (category.children.length > 0) {
        return {
          ...category,
          children: updateCategoryInTree(category.children, categoryId, updates)
        };
      }
      return category;
    });
  };

  const removeCategoryFromTree = (categories: CategoryData[], categoryId: string): CategoryData[] => {
    return categories
      .filter(category => category.id !== categoryId)
      .map((category) => ({
        ...category,
        children: category.children.length > 0 ? removeCategoryFromTree(category.children, categoryId) : category.children,
      }));
  };

  const addChildToCategory = (categories: CategoryData[], parentId: string, newCategory: CategoryData): CategoryData[] => {
    return categories.map(category => {
      if (category.id === parentId) {
        return {
          ...category,
          children: [...category.children, newCategory]
        };
      }
      if (category.children.length > 0) {
        return {
          ...category,
          children: addChildToCategory(category.children, parentId, newCategory)
        };
      }
      return category;
    });
  };

  const getAllCategoriesFlat = (categories: CategoryData[]): CategoryData[] => {
    const flat: CategoryData[] = [];
    const traverse = (cats: CategoryData[]) => {
      cats.forEach(cat => {
        flat.push(cat);
        if (cat.children.length > 0) {
          traverse(cat.children);
        }
      });
    };
    traverse(categories);
    return flat;
  };

  const allCategoriesFlat = useMemo(() => getAllCategoriesFlat(categories), [categories]);
  const totalCategories = allCategoriesFlat.length;
  const activeCategories = allCategoriesFlat.filter(cat => cat.isActive).length;
  const rootCategories = categories.length;
  const subCategories = Math.max(0, totalCategories - rootCategories);

  const handleSaveSettings = () => {
    toast({
      title: "Configuration enregistr├®e",
      description: `Profondeur: ${maxDepth}, max/niveau: ${maxCategoriesPerLevel}`,
    });
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold">Gestion des Cat├®gories</h1>
        <Button onClick={() => { setEditingCategory(null); setIsEditorOpen(true); }} disabled={isSaving}>
          <Plus className="w-4 h-4 mr-2" />
          Nouvelle Cat├®gorie
        </Button>
      </div>

      {/* Statistiques */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Cat├®gories Totales</CardTitle>
            <FolderTree className="h-4 w-4 text-blue-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{isLoading ? "ÔÇª" : totalCategories}</div>
            <p className="text-xs text-muted-foreground">{activeCategories} actives</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Cat├®gories Principales</CardTitle>
            <FolderTree className="h-4 w-4 text-green-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{isLoading ? "ÔÇª" : rootCategories}</div>
            <p className="text-xs text-muted-foreground">Niveau racine</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Sous-cat├®gories</CardTitle>
            <FolderTree className="h-4 w-4 text-purple-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{isLoading ? "ÔÇª" : subCategories}</div>
            <p className="text-xs text-muted-foreground">Niveaux inf├®rieurs</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Annonces Totales</CardTitle>
            <Eye className="h-4 w-4 text-orange-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{isLoading ? "ÔÇª" : totalAnnouncementsExact.toLocaleString()}</div>
            <p className="text-xs text-muted-foreground">Dans toutes les cat├®gories</p>
          </CardContent>
        </Card>
      </div>

      {/* Onglets principaux */}
      <Tabs value={selectedTab} onValueChange={setSelectedTab}>
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="list">Liste & Arborescence</TabsTrigger>
          <TabsTrigger value="bulk">Actions en Lot</TabsTrigger>
          <TabsTrigger value="settings">Configuration</TabsTrigger>
        </TabsList>

        <TabsContent value="list" className="space-y-6">
          <CategoryTreeView
            categories={categories}
            onEdit={handleEditCategory}
            onDelete={handleDeleteCategory}
            onToggleStatus={handleToggleStatus}
            onMove={handleMoveCategory}
          />
        </TabsContent>

        <TabsContent value="bulk">
          <CategoryBulkActions />
        </TabsContent>

        <TabsContent value="settings">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <Settings className="w-5 h-5" />
                <span>Configuration G├®n├®rale</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Profondeur maximale de l'arborescence</Label>
                  <Input
                    type="number"
                    value={maxDepth}
                    min={1}
                    onChange={(e) => setMaxDepth(Number(e.target.value || 1))}
                  />
                </div>
                <div>
                  <Label>Nombre max de cat├®gories par niveau</Label>
                  <Input
                    type="number"
                    value={maxCategoriesPerLevel}
                    min={1}
                    onChange={(e) => setMaxCategoriesPerLevel(Number(e.target.value || 1))}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex items-center space-x-2">
                  <Switch checked={autoSlug} onCheckedChange={setAutoSlug} />
                  <Label>G├®n├®ration automatique des slugs</Label>
                </div>
                <div className="flex items-center space-x-2">
                  <Switch checked={autoValidation} onCheckedChange={setAutoValidation} />
                  <Label>Validation automatique des nouvelles cat├®gories</Label>
                </div>
                <div className="flex items-center space-x-2">
                  <Switch checked={autoSave} onCheckedChange={setAutoSave} />
                  <Label>Sauvegarde automatique des modifications</Label>
                </div>
              </div>

              <Button onClick={handleSaveSettings}>
                <Database className="w-4 h-4 mr-2" />
                Sauvegarder la configuration
              </Button>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Dialogue d'├®dition */}
      <Dialog open={isEditorOpen} onOpenChange={setIsEditorOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingCategory ? 'Modifier la cat├®gorie' : 'Nouvelle cat├®gorie'}
            </DialogTitle>
          </DialogHeader>
          <CategoryEditor
            category={editingCategory || undefined}
            parentCategories={getAllCategoriesFlat(categories).filter(cat => !editingCategory || cat.id !== editingCategory.id)}
            onSave={handleSaveCategory}
            onCancel={() => setIsEditorOpen(false)}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CategoryManagement;

import { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Users, FileText, Eye, TrendingUp } from "lucide-react";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from "recharts";
import { OfflineMode } from "@/components/offline/OfflineMode";
import { supabase } from "@/integrations/supabase/client";
import { logger } from "@/utils/silentLogger";

type DashboardStat = {
  title: string;
  value: string;
  change: string;
  changeClassName: string;
  icon: typeof Users;
  color: string;
};

const DashboardHome = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<DashboardStat[]>([]);
  const [chartData, setChartData] = useState<Array<{ name: string; annonces: number; utilisateurs: number }>>([]);
  const [recentActivities, setRecentActivities] = useState<Array<{ id: string; type: "success" | "warning" | "info"; message: string; time: string }>>([]);

  const formatPercent = (current: number, previous: number) => {
    if (previous <= 0 && current <= 0) return { text: "0%", className: "text-muted-foreground" };
    if (previous <= 0 && current > 0) return { text: "+100%", className: "text-green-600" };
    const delta = ((current - previous) / previous) * 100;
    const rounded = Math.round(delta);
    return {
      text: `${rounded >= 0 ? "+" : ""}${rounded}%`,
      className: rounded >= 0 ? "text-green-600" : "text-red-600",
    };
  };

  const monthLabel = (date: Date) =>
    date
      .toLocaleDateString("fr-FR", { month: "short" })
      .replace(".", "")
      .replace(/^./, (c) => c.toUpperCase());

  const relativeTime = (iso: string) => {
    const then = new Date(iso).getTime();
    const now = Date.now();
    const diffMinutes = Math.max(0, Math.floor((now - then) / 60000));
    if (diffMinutes < 1) return "├Ç l'instant";
    if (diffMinutes < 60) return `Il y a ${diffMinutes} min`;
    const diffHours = Math.floor(diffMinutes / 60);
    if (diffHours < 24) return `Il y a ${diffHours} h`;
    const diffDays = Math.floor(diffHours / 24);
    return `Il y a ${diffDays} j`;
  };

  useEffect(() => {
    const loadDashboard = async () => {
      setLoading(true);
      try {
        const now = new Date();
        const startCurrentMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const startNextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
        const startPreviousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        const startThirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        const startSixMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 5, 1);

        const [
          profilesTotalRes,
          profilesActiveRes,
          profilesCurrentMonthRes,
          profilesPreviousMonthRes,
          profilesSixMonthsRes,
          announcementsTotalRes,
          announcementsCurrentMonthRes,
          announcementsPreviousMonthRes,
          announcementsSixMonthsRes,
          announcementsViewsRes,
          bannersActiveRes,
          bannersTotalRes,
          latestAnnouncementsRes,
          latestReportsRes,
          latestProfilesRes,
          latestBannersRes,
        ] = await Promise.all([
          supabase.from("profiles").select("id", { count: "exact", head: true }),
          supabase.from("profiles").select("id", { count: "exact", head: true }).gte("updated_at", startThirtyDaysAgo.toISOString()),
          supabase.from("profiles").select("id", { count: "exact", head: true }).gte("created_at", startCurrentMonth.toISOString()).lt("created_at", startNextMonth.toISOString()),
          supabase.from("profiles").select("id", { count: "exact", head: true }).gte("created_at", startPreviousMonth.toISOString()).lt("created_at", startCurrentMonth.toISOString()),
          supabase.from("profiles").select("created_at").gte("created_at", startSixMonthsAgo.toISOString()),
          supabase.from("announcements_public").select("id", { count: "exact", head: true }).eq("status", "active"),
          supabase.from("announcements_public").select("id", { count: "exact", head: true }).eq("status", "active").gte("created_at", startCurrentMonth.toISOString()).lt("created_at", startNextMonth.toISOString()),
          supabase.from("announcements_public").select("id", { count: "exact", head: true }).eq("status", "active").gte("created_at", startPreviousMonth.toISOString()).lt("created_at", startCurrentMonth.toISOString()),
          supabase.from("announcements_public").select("created_at").eq("status", "active").gte("created_at", startSixMonthsAgo.toISOString()),
          supabase.from("announcements").select("view_count, created_at").eq("status", "active"),
          supabase.from("advertising_banners").select("id", { count: "exact", head: true }).eq("is_active", true),
          supabase.from("advertising_banners").select("id", { count: "exact", head: true }),
          supabase.from("announcements_public").select("id, title, created_at").eq("status", "active").order("created_at", { ascending: false }).limit(3),
          supabase.from("reports").select("id, target_title, created_at").order("created_at", { ascending: false }).limit(2),
          supabase.from("profiles").select("id, first_name, last_name, created_at").order("created_at", { ascending: false }).limit(2),
          supabase.from("advertising_banners").select("id, title, created_at").eq("is_active", true).order("created_at", { ascending: false }).limit(1),
        ]);

        const activeUsers = profilesActiveRes.count || 0;
        const totalAnnouncements = announcementsTotalRes.count || 0;
        const activeBanners = bannersActiveRes.count || 0;
        const totalBanners = bannersTotalRes.count || 0;

        const viewsRows = (announcementsViewsRes.data || []) as Array<{ view_count: number | null; created_at: string | null }>;
        const totalViews = viewsRows.reduce((sum, row) => sum + (row.view_count || 0), 0);

        const currentMonthViews = viewsRows
          .filter((row) => row.created_at && new Date(row.created_at) >= startCurrentMonth && new Date(row.created_at) < startNextMonth)
          .reduce((sum, row) => sum + (row.view_count || 0), 0);
        const previousMonthViews = viewsRows
          .filter((row) => row.created_at && new Date(row.created_at) >= startPreviousMonth && new Date(row.created_at) < startCurrentMonth)
          .reduce((sum, row) => sum + (row.view_count || 0), 0);

        const usersTrend = formatPercent(profilesCurrentMonthRes.count || 0, profilesPreviousMonthRes.count || 0);
        const announcementsTrend = formatPercent(announcementsCurrentMonthRes.count || 0, announcementsPreviousMonthRes.count || 0);
        const viewsTrend = formatPercent(currentMonthViews, previousMonthViews);

        setStats([
          {
            title: "Utilisateurs Actifs",
            value: activeUsers.toLocaleString("fr-FR"),
            change: usersTrend.text,
            changeClassName: usersTrend.className,
            icon: Users,
            color: "text-blue-600",
          },
          {
            title: "Annonces Publi├®es",
            value: totalAnnouncements.toLocaleString("fr-FR"),
            change: announcementsTrend.text,
            changeClassName: announcementsTrend.className,
            icon: FileText,
            color: "text-green-600",
          },
          {
            title: "Vues Totales",
            value: totalViews.toLocaleString("fr-FR"),
            change: viewsTrend.text,
            changeClassName: viewsTrend.className,
            icon: Eye,
            color: "text-purple-600",
          },
          {
            title: "Banni├¿res Actives",
            value: activeBanners.toLocaleString("fr-FR"),
            change: `${totalBanners.toLocaleString("fr-FR")} total`,
            changeClassName: "text-orange-600",
            icon: TrendingUp,
            color: "text-orange-600",
          },
        ]);

        const monthBuckets: Array<{ monthDate: Date; name: string; annonces: number; utilisateurs: number }> = Array.from({ length: 6 }).map((_, idx) => {
          const d = new Date(now.getFullYear(), now.getMonth() - (5 - idx), 1);
          return { monthDate: d, name: monthLabel(d), annonces: 0, utilisateurs: 0 };
        });

        const byKey = new Map(monthBuckets.map((m) => [`${m.monthDate.getFullYear()}-${m.monthDate.getMonth()}`, m]));

        ((announcementsSixMonthsRes.data || []) as Array<{ created_at: string | null }>).forEach((row) => {
          if (!row.created_at) return;
          const d = new Date(row.created_at);
          const key = `${d.getFullYear()}-${d.getMonth()}`;
          const target = byKey.get(key);
          if (target) target.annonces += 1;
        });

        ((profilesSixMonthsRes.data || []) as Array<{ created_at: string | null }>).forEach((row) => {
          if (!row.created_at) return;
          const d = new Date(row.created_at);
          const key = `${d.getFullYear()}-${d.getMonth()}`;
          const target = byKey.get(key);
          if (target) target.utilisateurs += 1;
        });

        setChartData(monthBuckets.map(({ name, annonces, utilisateurs }) => ({ name, annonces, utilisateurs })));

        const activitiesRaw: Array<{ id: string; created_at: string; type: "success" | "warning" | "info"; message: string }> = [];

        ((latestAnnouncementsRes.data || []) as Array<{ id: string; title: string | null; created_at: string | null }>).forEach((item) => {
          if (!item.created_at) return;
          activitiesRaw.push({
            id: `a-${item.id}`,
            created_at: item.created_at,
            type: "success",
            message: `Nouvelle annonce publi├®e: ${item.title || "Sans titre"}`,
          });
        });

        ((latestReportsRes.data || []) as Array<{ id: string; target_title: string | null; created_at: string | null }>).forEach((item) => {
          if (!item.created_at) return;
          activitiesRaw.push({
            id: `r-${item.id}`,
            created_at: item.created_at,
            type: "warning",
            message: `Annonce signal├®e: ${item.target_title || "Cible non renseign├®e"}`,
          });
        });

        ((latestProfilesRes.data || []) as Array<{ id: string; first_name: string | null; last_name: string | null; created_at: string | null }>).forEach((item) => {
          if (!item.created_at) return;
          const fullName = `${item.first_name || ""} ${item.last_name || ""}`.trim() || "Utilisateur";
          activitiesRaw.push({
            id: `u-${item.id}`,
            created_at: item.created_at,
            type: "info",
            message: `Nouvel utilisateur inscrit: ${fullName}`,
          });
        });

        ((latestBannersRes.data || []) as Array<{ id: string; title: string | null; created_at: string | null }>).forEach((item) => {
          if (!item.created_at) return;
          activitiesRaw.push({
            id: `b-${item.id}`,
            created_at: item.created_at,
            type: "success",
            message: `Banni├¿re publicitaire active: ${item.title || "Sans titre"}`,
          });
        });

        activitiesRaw.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
        setRecentActivities(
          activitiesRaw.slice(0, 8).map((item) => ({
            id: item.id,
            type: item.type,
            message: item.message,
            time: relativeTime(item.created_at),
          }))
        );
      } catch (error) {
        logger.error("Erreur chargement dashboard admin:", error);
        setStats([
          { title: "Utilisateurs Actifs", value: "0", change: "0%", changeClassName: "text-muted-foreground", icon: Users, color: "text-blue-600" },
          { title: "Annonces Publi├®es", value: "0", change: "0%", changeClassName: "text-muted-foreground", icon: FileText, color: "text-green-600" },
          { title: "Vues Totales", value: "0", change: "0%", changeClassName: "text-muted-foreground", icon: Eye, color: "text-purple-600" },
          { title: "Banni├¿res Actives", value: "0", change: "0 total", changeClassName: "text-muted-foreground", icon: TrendingUp, color: "text-orange-600" },
        ]);
        setChartData([]);
        setRecentActivities([]);
      } finally {
        setLoading(false);
      }
    };

    void loadDashboard();
  }, []);

  const chartDataSafe = useMemo(
    () => (chartData.length > 0 ? chartData : [{ name: "ÔÇö", annonces: 0, utilisateurs: 0 }]),
    [chartData]
  );

  return (
    <div className="p-6 space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, index) => (
          <Card key={index}>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">{stat.title}</CardTitle>
              <stat.icon className={`h-4 w-4 ${stat.color}`} />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stat.value}</div>
              <p className="text-xs text-muted-foreground">
                <span className={stat.changeClassName}>{stat.change}</span> {stat.title === "Banni├¿res Actives" ? "" : "par rapport au mois dernier"}
              </p>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>├ëvolution des Annonces</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={chartDataSafe}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Line type="monotone" dataKey="annonces" stroke="#8884d8" strokeWidth={2} />
              </LineChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Utilisateurs par Mois</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={chartDataSafe}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="utilisateurs" fill="#82ca9d" />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Activit├®s R├®centes</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {loading ? (
              <p className="text-sm text-muted-foreground">Chargement des activit├®s...</p>
            ) : recentActivities.length === 0 ? (
              <p className="text-sm text-muted-foreground">Aucune activit├® r├®cente</p>
            ) : recentActivities.map((activity) => (
              <div key={activity.id} className="flex items-center space-x-4">
                <div className={`w-2 h-2 rounded-full ${
                  activity.type === 'success' ? 'bg-green-500' :
                  activity.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'
                }`} />
                <div className="flex-1">
                  <p className="text-sm font-medium">{activity.message}</p>
                  <p className="text-xs text-gray-500">{activity.time}</p>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Mode Hors-Ligne */}
      <OfflineMode />
    </div>
  );
};

export default DashboardHome;

import { useEffect, useState, useCallback, useMemo } from "react"
import { useParams } from "react-router-dom"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { ArrowLeft, Copy, Mail, Phone, ShieldCheck, Calendar, FileText, Ban, Undo2, Send, EyeOff } from "lucide-react"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from "@/components/ui/select"
import { useAuth } from "@/contexts/useAuth"
import { supabase } from "@/integrations/supabase/client"
import { useToast } from "@/hooks/use-toast"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import ConfirmDialog from "@/components/common/ConfirmDialog"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"

interface Profile {
  id: string
  user_id: string | null
  public_user_id: number | null
  display_name: string | null
  first_name: string | null
  last_name: string | null
  email?: string | null
  phone?: string | null
  avatar_url?: string | null
  bio?: string | null
  location?: string | null
  created_at?: string | null
