import { useState, useEffect, useCallback } from "react";
import { useSearchParams } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Users, UserCheck, UserX, Shield, Eye, Edit, Ban, RefreshCw, Mail, Phone, ShieldCheck, AlertCircle, Copy } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/contexts/useAuth";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { logger } from '@/utils/silentLogger';
import ConfirmDialog from "@/components/common/ConfirmDialog";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

interface UserProfile {
  id: string;
  user_id: string;
  public_user_id?: number | null;
  display_name?: string | null;
  avatar_url?: string | null;
  bio?: string | null;
  created_at: string;
  updated_at: string;
  // Calculated fields
  email: string;
  phone?: string | null;
  announcements_count?: number;
  last_sign_in_at?: string;
  is_premium?: boolean;
  profile_locked?: boolean;
  role?: "admin" | "moderator" | "user" | null;
  is_protected_admin?: boolean;
}

const UserManagement = () => {
  const { toast } = useToast();
  const { user: currentUser } = useAuth();
  const [searchParams] = useSearchParams();
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [stats, setStats] = useState({
    total: 0,
    active: 0,
    premium: 0,
    new_today: 0
  });
  const [pendingUserSuspension, setPendingUserSuspension] = useState<UserProfile | null>(null);
  const [canManageSuspension, setCanManageSuspension] = useState(false);

  useEffect(() => {
    const resolvePermission = async () => {
      if (!currentUser?.id) {
        setCanManageSuspension(false);
        return;
      }

      const { data } = await supabase
        .from("user_roles")
        .select("role")
        .eq("user_id", currentUser.id);
      const roles = (data || []).map((r: { role: "admin" | "moderator" | "user" }) => r.role);
      setCanManageSuspension(roles.includes("admin") || roles.includes("moderator"));
    };

    void resolvePermission();
  }, [currentUser]);

  const fetchUsers = useCallback(async () => {
    try {
      setLoading(true);

      // Fetch user profiles
      const { data: profiles, error: profilesError } = await supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });

      if (profilesError) throw profilesError;

      const profileUserIds = (profiles || [])
        .map((p) => p.user_id)
        .filter((v): v is string => Boolean(v));

      let roleMap = new Map<string, "admin" | "moderator" | "user">();
      if (profileUserIds.length > 0) {
        const { data: rolesData } = await supabase
          .from("user_roles")
          .select("user_id, role")
          .in("user_id", profileUserIds);

        (rolesData || []).forEach((r: { user_id: string; role: "admin" | "moderator" | "user" }) => {
          const current = roleMap.get(r.user_id);
          if (current === "admin") return;
          if (current === "moderator" && r.role === "user") return;
          roleMap.set(r.user_id, r.role);
        });
      }

      // For each user, count their banners
      const usersWithStats = await Promise.all(
        (profiles || []).map(async (profile) => {
          const { count: bannersCount } = await supabase
            .from('advertising_banners')
            .select('*', { count: 'exact' })
            .eq('created_by', profile.user_id || '');

          const role = roleMap.get(profile.user_id || "") || null;
          const profileRecord = profile as unknown as Record<string, unknown>;
          const isProtectedAdmin =
            role === "admin" ||
            role === "moderator" ||
            (!!currentUser?.id && profile.user_id === currentUser.id);

          return {
            id: profile.id,
            user_id: profile.user_id || '',
            public_user_id: profile.public_user_id || null,
            display_name: profileRecord.display_name as string | null,
            avatar_url: profile.avatar_url,
            bio: profile.bio,
            created_at: profile.created_at || new Date().toISOString(),
            updated_at: profile.updated_at || new Date().toISOString(),
            email: (profileRecord.email as string) || '',
            phone: (profileRecord.phone as string) || null,
            announcements_count: bannersCount || 0,
            is_premium: (bannersCount || 0) > 2, // Simple premium logic
            profile_locked: profile.profile_locked || false,
            role,
            is_protected_admin: isProtectedAdmin,
          };
        })
      );

      setUsers(usersWithStats);

      // Calculate stats
      const total = usersWithStats.length;
      const premium = usersWithStats.filter(u => u.is_premium).length;
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const new_today = usersWithStats.filter(u => u.created_at && new Date(u.created_at) >= today).length;

      setStats({ 
        total, 
        active: total, // For now, consider all as active
        premium, 
        new_today 
      });

    } catch (error) {
      logger.error('Error fetching users:', error);
      toast({
        title: "Erreur",
        description: "Impossible de charger les utilisateurs",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  }, [currentUser?.id, toast]);

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  useEffect(() => {
    const q = searchParams.get("q");
    if (q && q.trim()) {
      setSearchTerm(q.trim());
    }
  }, [searchParams]);

  const filteredUsers = users.filter(user => {
    const term = searchTerm.toLowerCase();
    const digitsTerm = searchTerm.replace(/\D/g, '');
    const idRaw = user.public_user_id != null ? String(user.public_user_id) : '';
    const idPadded = user.public_user_id != null ? String(user.public_user_id).padStart(14, '0') : '';
    const phoneStr = (user.phone || '').toLowerCase();
    const phoneDigits = (user.phone || '').replace(/\D/g, '');
    return (
      (user.display_name || '').toLowerCase().includes(term) ||
      (user.email || '').toLowerCase().includes(term) ||
      (user.bio || '').toLowerCase().includes(term) ||
      idRaw.includes(searchTerm) ||
      idPadded.includes(searchTerm) ||
      phoneStr.includes(term) ||
      (digitsTerm.length >= 5 && phoneDigits.includes(digitsTerm))
    );
  });

  const handleCopy = (value: string, label?: string) => {
    navigator.clipboard.writeText(value);
    toast({
      title: "Copi├®",
      description: label ? `${label} copi├® dans le presse-papiers` : "Copi├® dans le presse-papiers",
