      });
      return;
    }
    if (targetUser.is_protected_admin) {
      toast({
        title: "Action bloqu├®e",
        description: "La suspension est d├®sactiv├®e pour les comptes administrateur/mod├®rateur.",
        variant: "destructive"
      });
      return;
    }
    try {
      const nextLocked = !targetUser.profile_locked;
      const sessionId = (typeof crypto !== "undefined" && "randomUUID" in crypto) ? crypto.randomUUID() : String(Date.now());

      const { error: rpcError } = await supabase.rpc("admin_set_profile_locked", {
        p_profile_id: targetUser.id,
        p_locked: nextLocked,
        p_reason: null,
        p_note: "Action rapide depuis la liste utilisateurs",
        p_session_id: sessionId
      });

      if (rpcError) {
        const { error: directError } = await supabase
          .from("profiles")
          .update({ profile_locked: nextLocked })
          .eq("id", targetUser.id);
        if (directError) {
          const needsDbFix = /ambiguous/i.test(rpcError.message || "");
          toast({
            title: "Erreur",
            description: needsDbFix
              ? "La fonction SQL de suspension doit ├¬tre mise ├á jour (ambiguous id). Ex├®cutez la migration corrective puis r├®essayez."
              : `Impossible de modifier l'├®tat du compte (RPC: ${rpcError.message} / Direct: ${directError.message})`,
            variant: "destructive"
          });
          return;
        }
      }

      toast({
        title: nextLocked ? "Compte d├®sactiv├®" : "Compte r├®activ├®",
        description: "L'├®tat du compte a ├®t├® mis ├á jour",
      });
      await fetchUsers();
    } catch (error) {
      logger.error("Error toggling user suspension:", error);
      toast({
        title: "Erreur",
        description: "Impossible de modifier l'├®tat du compte",
        variant: "destructive"
      });
    }
  };

  const confirmToggleUserSuspension = async () => {
    if (!pendingUserSuspension) return;
    const selected = pendingUserSuspension;
    setPendingUserSuspension(null);
    await toggleUserSuspension(selected);
  };

  if (loading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <ConfirmDialog
        isOpen={!!pendingUserSuspension}
        onClose={() => setPendingUserSuspension(null)}
        onConfirm={confirmToggleUserSuspension}
        title={pendingUserSuspension?.profile_locked ? "R├®activer le compte ?" : "D├®sactiver le compte ?"}
        description={
          pendingUserSuspension?.profile_locked
            ? "Ce compte utilisateur sera r├®activ├®."
            : "Ce compte utilisateur sera suspendu."
        }
        confirmText={pendingUserSuspension?.profile_locked ? "R├®activer" : "D├®sactiver"}
        cancelText="Annuler"
        variant="destructive"
      />
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold">Gestion des Utilisateurs</h1>
        <div className="flex space-x-2">
          <Input 
            placeholder="Rechercher nom, email, t├®l├®phone ou ID utilisateur..." 
            className="w-64"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <Button onClick={fetchUsers} variant="outline">
            <RefreshCw className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Utilisateurs Totaux</CardTitle>
            <Users className="h-4 w-4 text-blue-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
            <p className="text-xs text-muted-foreground">Comptes cr├®├®s</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Actifs</CardTitle>
            <UserCheck className="h-4 w-4 text-green-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.active}</div>
            <p className="text-xs text-muted-foreground">Comptes actifs</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Premium</CardTitle>
            <Shield className="h-4 w-4 text-purple-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.premium}</div>
            <p className="text-xs text-muted-foreground">Utilisateurs premium</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Nouveaux</CardTitle>
            <UserX className="h-4 w-4 text-orange-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.new_today}</div>
            <p className="text-xs text-muted-foreground">Inscrits aujourd'hui</p>
          </CardContent>
        </Card>
      </div>

      {/* Users List */}
      <Card>
        <CardHeader>
          <CardTitle>Liste des Utilisateurs ({filteredUsers.length})</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {filteredUsers.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                <Users className="h-12 w-12 mx-auto mb-4 opacity-50" />
                <p>Aucun utilisateur trouv├®</p>
              </div>
            ) : (
              filteredUsers.map((user) => (
                <div key={user.id} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                  <div className="flex items-center space-x-4">
                    <Avatar className="h-12 w-12">
                      <AvatarImage src={user.avatar_url || undefined} alt={user.display_name || undefined} />
                      <AvatarFallback>
                        {user.display_name?.charAt(0) || user.email.charAt(0).toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1">
                      <h3 className="font-semibold">
                        {user.display_name || 'Nom non renseign├®'}
                        {user.public_user_id != null && (
                          <Badge variant="outline" className="ml-2 font-mono">
                            ID utilisateur: {String(user.public_user_id).padStart(14, '0')}
                          </Badge>
                          )}
                          {user.public_user_id != null && (
                            <Button 
                              variant="outline" 
                              size="icon" 
                              className="ml-2"
                              onClick={() => handleCopy(String(user.public_user_id).padStart(14, '0'), 'ID utilisateur')}
                            >
                              <Copy className="w-3 h-3" />
                            </Button>
                         )}
                      </h3>
                      <p className="text-sm text-muted-foreground flex items-center gap-1">
                        <Mail className="w-3 h-3" />
                        {user.email}
                        {!!user.email && (
                          <Button 
                            variant="ghost" 
                            size="icon" 
                            className="ml-1"
                            onClick={() => handleCopy(user.email, 'Email')}
                          >
                            <Copy className="w-3 h-3" />
                          </Button>
                        )}
                      </p>
                      {user.phone && (
                        <p className="text-sm text-muted-foreground flex items-center gap-1">
                          <Phone className="w-3 h-3" />
                          {user.phone}
                          <Button 
                            variant="ghost" 
                            size="icon" 
                            className="ml-1"
                            onClick={() => handleCopy(user.phone || '', 'T├®l├®phone')}
                          >
                            <Copy className="w-3 h-3" />
                          </Button>
                        </p>
                      )}
                      <div className="flex items-center gap-2 mt-1">
                        {user.email ? (
                          <Badge variant="outline" className="bg-green-50 text-green-700">
                            <ShieldCheck className="w-3 h-3 mr-1" />
