                            <Phone className="w-3 h-3 mr-1" />
                            T├®l├®phone renseign├®
                          </Badge>
                        )}
                      </div>
                      {user.bio && (
                        <p className="text-xs text-muted-foreground">{user.bio}</p>
                      )}
                      <div className="flex items-center space-x-4 mt-2">
                        <span className="text-xs text-muted-foreground">
