                          </Badge>
                        )}
                        {user.profile_locked && (
                          <Badge variant="destructive">
                            <Ban className="w-3 h-3 mr-1" />
                            Compte d├®sactiv├®
                          </Badge>
                        )}
                        {user.is_protected_admin && (
                          <Badge variant="secondary">
                            <Shield className="w-3 h-3 mr-1" />
                            Compte prot├®g├®
                          </Badge>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => window.open(`/admin/users/${user.id}`, '_blank')}
                    >
                      <Eye className="w-4 h-4 mr-1" />
                      Voir compte
                    </Button>
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => window.open(`/admin/users/${user.id}`, '_blank')}
                    >
                      <Edit className="w-4 h-4" />
                    </Button>
                    <TooltipProvider>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button 
                            variant={user.profile_locked ? "secondary" : "destructive"} 
                            size="sm"
                            disabled={!!user.is_protected_admin || !canManageSuspension}
                            onClick={() => setPendingUserSuspension(user)}
                          >
                            <Ban className="w-4 h-4" />
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent side="top">
                          {!canManageSuspension
                            ? "Votre r├┤le ne permet pas la suspension de comptes"
                            : user.is_protected_admin
                              ? "Suspension non autoris├®e pour ce compte prot├®g├®"
                              : user.profile_locked
                                ? "R├®activer le compte"
                                : "D├®sactiver le compte"}
                        </TooltipContent>
                      </Tooltip>
                    </TooltipProvider>
                  </div>
                </div>
              ))
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

