  showActions?: boolean;
}

const AnnouncementCard: React.FC<AnnouncementCardProps> = ({
  announcement,
  onView,
  onContact,
  onShare,
  variant = 'default',
  showActions = true
}) => {
  const { fetchFavorites, isFavorite, toggleFavorite } = useFavorites();
  const { t, isRTL, language } = useSafeI18nWithRouter();

  const announcementUrl = `${window.location.origin}/annonce/${announcement.id}`;
  const shareTitle = announcement.title;

  useEffect(() => {
    fetchFavorites();
  }, [fetchFavorites]);

  const handleShare = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      navigator.share({
        title: shareTitle,
        url: announcementUrl,
      }).catch(() => {
        copyToClipboard();
      });
    } else {
      copyToClipboard();
    }
  };

  const handleWhatsAppShare = (e: React.MouseEvent) => {
    e.stopPropagation();
    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(shareTitle + " - " + announcementUrl)}`;
    window.open(whatsappUrl, '_blank');
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(announcementUrl);
    toast.success(t('common.linkCopied') || "Lien copi├â┬® !", {
      description: t('common.linkCopiedDesc') || "Le lien a ├â┬®t├â┬® copi├â┬® dans votre presse-papiers."
    });
  };
  const localizeLabel = (s: string | undefined, language: string, kind?: string) => {
    if (!s) return s;
    let r = String(s);
    if (language === 'ar') {
      r = r.replace(/\bGB\b|\bGo\b/gi, '├ÿ┬║├Ö┼á├ÿ┬║├ÿ┬º├ÿ┬¿├ÿ┬º├Ö┼á├ÿ┬¬');
      r = r.replace(/\bTB\b|\bTo\b/gi, '├ÿ┬¬├Ö┼á├ÿ┬▒├ÿ┬º├ÿ┬¿├ÿ┬º├Ö┼á├ÿ┬¬');
      r = r.replace(/\bHz\b/gi, '├ÖÔÇí├ÿ┬▒├ÿ┬¬├ÿ┬▓');
      r = r.replace(/(\d{1,2}(?:\.\d)?)"/g, '$1 ├ÿ┬¿├Ö╦å├ÿ┬Á├ÿ┬®');
      r = r.replace(/\bcarbone\b|carbon/gi, '├ÖãÆ├ÿ┬▒├ÿ┬¿├Ö╦å├ÖÔÇá');
      r = r.replace(/\baluminium\b|alu/gi, '├ÿ┬ú├ÖÔÇ×├ÖÔÇª├ÖÔÇá├Ö┼á├Ö╦å├ÖÔÇª');
      r = r.replace(/\bacier\b|steel/gi, '├Ö┬ü├Ö╦å├ÖÔÇ×├ÿ┬º├ÿ┬░');
      r = r.replace(/\bfull[- ]?suspension\b|tout\s?suspendu|full/gi, '├ÿ┬¬├ÿ┬╣├ÖÔÇ×├Ö┼á├ÖÔÇÜ ├ÖãÆ├ÿ┬º├ÖÔÇª├ÖÔÇ×');
      r = r.replace(/\bsemi[- ]?rigide\b|hardtail/gi, '├ÿ┬¬├ÿ┬╣├ÖÔÇ×├Ö┼á├ÖÔÇÜ ├ÿ┬ú├ÖÔÇª├ÿ┬º├ÖÔÇª├Ö┼á ├Ö┬ü├ÖÔÇÜ├ÿ┬À');
      r = r.replace(/\bdisque\b|disc/gi, '├ÖÔÇÜ├ÿ┬▒├ÿ┬Á├Ö┼á');
      r = r.replace(/\bhydraulique\b/gi, '├ÖÔÇí├Ö┼á├ÿ┬»├ÿ┬▒├Ö╦å├ÖÔÇ×├Ö┼á├ÖãÆ');
      r = r.replace(/\bv[- ]?brake\b|patins/gi, '├ÿ┬¡├ÿ┬░├Ö╦å├ÿ┬®');
      r = r.replace(/\bkg\b/gi, '├ÖãÆ├ÖÔÇ×├ÿ┬║');
      if (kind === 'gears') {
        const m = r.match(/^\d{1,2}$/);
        if (m) r = `${m[0]} ├ÿ┬│├ÿ┬▒├ÿ┬╣├ÿ┬º├ÿ┬¬`;
      }
      if (kind === 'os') {
        r = r.replace(/windows/gi, '├Ö╦å├Ö┼á├ÖÔÇá├ÿ┬»├Ö╦å├ÿ┬▓').replace(/macos/gi, '├ÖÔÇª├ÿ┬º├ÖãÆ ├ÿ┬ú├Ö╦å ├ÿ┬Ñ├ÿ┬│').replace(/linux/gi, '├ÖÔÇ×├Ö┼á├ÖÔÇá├ÖãÆ├ÿ┬│').replace(/ubuntu/gi, '├ÿ┬ú├Ö╦å├ÿ┬¿├Ö╦å├ÖÔÇá├ÿ┬¬├Ö╦å');
      }
    } else {
      r = r.replace(/\bGB\b|\bGo\b/gi, 'Go');
      r = r.replace(/\bTB\b|\bTo\b/gi, 'To');
      r = r.replace(/\bHz\b/gi, 'Hz');
      r = r.replace(/(\d{1,2}(?:\.\d)?)\s*(?:"|pouce|pouces|inch|in)/gi, (_, n) => `${n}"`);
      if (kind === 'gears') {
        const m = r.match(/^\d{1,2}$/);
        if (m) r = `${m[0]} vitesses`;
      }
    }
    return r;
  };

  const formatPrice = (price: number | null) => {
    if (!price || price === 0) {
      return (
        <Badge variant="secondary" className="bg-emerald-100 text-emerald-800 border-emerald-200 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider">
          {t('createAd.priceByContact') || 'Prix par contact'}
        </Badge>
      );
    }

    // Conversion en millions de centimes (standard alg├â┬®rien)
    // 1 million de centimes = 10 000 DZD
    const millionsCentimes = Math.floor(price / 10_000);
    return `${millionsCentimes.toLocaleString()} M`;
  };

  const getConditionBadge = (condition: string | null) => {
    const badges = {
      new: { label: t('announcements.condition.new') || 'Neuf', variant: 'default' as const },
      like_new: { label: t('announcements.condition.likeNew') || 'Comme neuf', variant: 'secondary' as const },
      good: { label: t('announcements.condition.good') || 'Bon ├®tat', variant: 'outline' as const },
      fair: { label: t('announcements.condition.fair') || '├ëtat correct', variant: 'outline' as const },
      poor: { label: t('announcements.condition.poor') || '├Ç r├®nover', variant: 'destructive' as const },
    };
    return badges[(condition as keyof typeof badges)] || badges.good;
  };

  const conditionBadge = getConditionBadge(announcement.condition);
  const isFav = isFavorite(announcement.id);

