      } else {
        // For non-authenticated users, use session storage
        const history = JSON.parse(sessionStorage.getItem('searchHistory') || '[]');
        setSearchHistory(history);
      }
    } catch (error) {
      logger.error('Error fetching search history:', error);
    } finally {
      setLoading(false);
    }
  }, [user]);

  // Save a search (mock implementation)
  const saveSearch = useCallback(async (
    name: string, 
    query: string, 
    filters: Record<string, unknown>,
    enableNotifications = false
  ) => {
    if (!user) {
      toast({
        title: t('auth.loginRequired'),
        description: t('auth.loginRequiredDesc'),
      });
      return false;
    }

    try {
      // Mock implementation - store in localStorage for now
      const savedSearches = JSON.parse(localStorage.getItem('savedSearches') || '[]') as SavedSearch[];
      const newSearch = {
        id: Date.now().toString(),
        name,
        query,
        filters,
        user_id: user.id,
        notification_enabled: enableNotifications,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        last_checked: new Date().toISOString()
      };
      (savedSearches as SavedSearch[]).push(newSearch as SavedSearch);
      localStorage.setItem('savedSearches', JSON.stringify(savedSearches));

      toast({
        title: t('savedSearch.saved'),
        description: t('savedSearch.savedDesc'),
      });

      setSavedSearches(savedSearches);
      return true;
    } catch (error) {
      logger.error('Error saving search:', error);
      toast({
        title: t('common.error'),
        description: t('savedSearch.saveError'),
        variant: 'destructive',
      });
      return false;
    }
  }, [user, toast, t]);

  // Delete saved search (mock implementation)
  const deleteSavedSearch = useCallback(async (id: string) => {
    if (!user) return false;

    try {
      const savedSearches = JSON.parse(localStorage.getItem('savedSearches') || '[]') as SavedSearch[];
      const filteredSearches = (savedSearches as SavedSearch[]).filter((search) => search.id !== id);
      localStorage.setItem('savedSearches', JSON.stringify(filteredSearches));

      toast({
        title: t('savedSearch.deleted'),
        description: t('savedSearch.deletedDesc'),
      });

      setSavedSearches(filteredSearches);
      return true;
    } catch (error) {
      logger.error('Error deleting saved search:', error);
      toast({
        title: t('common.error'),
        description: t('savedSearch.deleteError'),
        variant: 'destructive',
      });
      return false;
    }
  }, [user, toast]);

  // Add to search history
  const addToHistory = useCallback(async (
    query: string,
    filters: Record<string, unknown>,
    resultsCount: number,
    searchTime: number
  ) => {
    const historyItem = {
      query,
      filters,
      results_count: resultsCount,
      search_time: searchTime,
      created_at: new Date().toISOString(),
      user_id: user?.id
    };

    if (user) {
      try {
        // Mock implementation - store in localStorage for now  
        const history = JSON.parse(localStorage.getItem('searchHistory') || '[]');
        history.unshift({ ...historyItem, id: Date.now().toString() });
        localStorage.setItem('searchHistory', JSON.stringify(history.slice(0, 50)));
        setSearchHistory(history.slice(0, 50));
      } catch (error) {
        logger.error('Error saving search to history:', error);
      }
    } else {
      // For non-authenticated users, use session storage
      const history = JSON.parse(sessionStorage.getItem('searchHistory') || '[]');
      history.unshift({ ...historyItem, id: Date.now().toString() });
      sessionStorage.setItem('searchHistory', JSON.stringify(history.slice(0, 50)));
      setSearchHistory(history.slice(0, 50));
    }
  }, [user]);

  // Clear search history
  const clearHistory = useCallback(async () => {
    if (user) {
      try {
        localStorage.removeItem('searchHistory');
      } catch (error) {
        logger.error('Error clearing search history:', error);
      }
    } else {
      sessionStorage.removeItem('searchHistory');
    }
    setSearchHistory([]);
    toast({
      title: t('savedSearch.historyCleared'),
      description: t('savedSearch.historyClearedDesc'),
    });
  }, [user, toast]);

  // Initialize data on mount - load from localStorage/sessionStorage
  useEffect(() => {
    if (user) {
      const savedSearches = JSON.parse(localStorage.getItem('savedSearches') || '[]');
      setSavedSearches(savedSearches);
      const history = JSON.parse(localStorage.getItem('searchHistory') || '[]');
      setSearchHistory(history);
    } else {
      const history = JSON.parse(sessionStorage.getItem('searchHistory') || '[]');
      setSearchHistory(history);
    }
  }, [user]);

  return {
    savedSearches,
    searchHistory,
    loading,
    saveSearch,
    deleteSavedSearch,
    addToHistory,
    clearHistory,
    fetchSavedSearches,
    fetchSearchHistory
  };
};

import { useState, useCallback } from 'react';
import { Language } from '../types/comprehensive';
import { logger } from '@/utils/silentLogger';

interface AdminHookState {
  isAdminOpen: boolean;
  isMonitorOpen: boolean;
  currentView: 'admin' | 'monitor' | null;
}

interface AdminControls {
  openAdmin: () => void;
  openMonitor: () => void;
  closeAll: () => void;
  toggleAdmin: () => void;
  toggleMonitor: () => void;
}

/**
 * Hook for managing translation admin interfaces
 */
export function useTranslationAdmin(): AdminHookState & AdminControls {
  const [state, setState] = useState<AdminHookState>({
    isAdminOpen: false,
    isMonitorOpen: false,
    currentView: null,
  });

  const openAdmin = useCallback(() => {
    setState({
      isAdminOpen: true,
      isMonitorOpen: false,
      currentView: 'admin',
    });
  }, []);

  const openMonitor = useCallback(() => {
    setState({
      isAdminOpen: false,
      isMonitorOpen: true,
      currentView: 'monitor',
    });
  }, []);

  const closeAll = useCallback(() => {
    setState({
      isAdminOpen: false,
      isMonitorOpen: false,
      currentView: null,
    });
  }, []);

  const toggleAdmin = useCallback(() => {
    setState(prev => ({
      isAdminOpen: !prev.isAdminOpen,
      isMonitorOpen: false,
      currentView: !prev.isAdminOpen ? 'admin' : null,
    }));
  }, []);

  const toggleMonitor = useCallback(() => {
    setState(prev => ({
      isAdminOpen: false,
      isMonitorOpen: !prev.isMonitorOpen,
      currentView: !prev.isMonitorOpen ? 'monitor' : null,
    }));
  }, []);

  return {
    ...state,
    openAdmin,
    openMonitor,
    closeAll,
    toggleAdmin,
    toggleMonitor,
  };
}

/**
 * Development helper to add admin access in dev mode
 */
export function useDevTranslationTools() {
  const admin = useTranslationAdmin();
  
  // Add keyboard shortcuts in development
  if (import.meta.env.MODE === 'development') {
    document.addEventListener('keydown', (e) => {
      // Ctrl/Cmd + Shift + T for admin
      if (e.ctrlKey && e.shiftKey && e.key === 'T') {
        e.preventDefault();
        admin.toggleAdmin();
      }
      
      // Ctrl/Cmd + Shift + M for monitor
      if (e.ctrlKey && e.shiftKey && e.key === 'M') {
        e.preventDefault();
        admin.toggleMonitor();
      }
    });
  }
  
  return admin;
}

/**
 * Hook for translation debugging in development
 */
export function useTranslationDebug() {
  const [debugMode, setDebugMode] = useState(
    import.meta.env.MODE === 'development' && 
    localStorage.getItem('translation-debug') === 'true'
  );

  const toggleDebug = useCallback(() => {
    const newMode = !debugMode;
    setDebugMode(newMode);
    localStorage.setItem('translation-debug', newMode.toString());
  }, [debugMode]);

  const logTranslation = useCallback((key: string, value: string, language: Language, source: 'direct' | 'fallback') => {
    if (debugMode) {
      const style = source === 'fallback' ? 'color: orange' : 'color: green';
      logger.info(`[i18n] ${language}: ${key} ÔåÆ ${value}`, source);
    }
  }, [debugMode]);

  const logMissingTranslation = useCallback((key: string, language: Language) => {
    if (debugMode) {
      logger.warn(`[i18n] Missing translation: ${key} (${language})`);
    }
  }, [debugMode]);

  return {
    debugMode,
    toggleDebug,
    logTranslation,
    logMissingTranslation,
  };
}

/**
 * Custom ESLint plugin to detect hardcoded text and enforce translation usage
 */
import { Rule } from 'eslint';
import { logger } from '@/utils/silentLogger';

interface EslintPluginTranslations {
  rules: Record<string, Rule.RuleModule>;
  configs: Record<string, unknown>;
}

const TRANSLATION_FUNCTIONS = ['t', 'translate', 'i18n.t'];
const ALLOWED_HARDCODED_PATTERNS = [
  /^[0-9\s+().-]+$/, // Numbers and simple math
  /^[A-Z_][A-Z0-9_]*$/, // Constants
  /^https?:\/\//, // URLs
  /^\//, // Paths
  /^[a-z0-9._-]+@[a-z0-9._-]+$/, // Emails
  /^\d{1,2}\/\d{1,2}\/\d{4}$/, // Dates
  /^#[0-9a-fA-F]{3,8}$/, // Colors
  /^[a-z0-9._-]+\.(jpg|jpeg|png|gif|svg|webp)$/i, // Image files
];

const COMPONENT_EXCEPTIONS = [
  'logger.log',
  'logger.error',
  'logger.warn',
  'logger.info',
  'logger.debug',
  'className',
  'id',
  'data-testid',
  'aria-label',
  'role',
  'type',
  'name',
  'value',
  'placeholder',
  'alt',
  'title',
  'href',
  'src',
  'key',
];

const noHardcodedStrings: Rule.RuleModule = {
  meta: {
    type: 'problem',
    docs: {
      description: 'Enforce use of translation functions instead of hardcoded strings',
      category: 'Internationalization',
      recommended: true,
    },
    fixable: 'code',
    schema: [
      {
        type: 'object',
        properties: {
          ignorePatterns: {
            type: 'array',
            items: { type: 'string' },
          },
          translationFunctions: {
            type: 'array',
            items: { type: 'string' },
          },
          allowedComponents: {
            type: 'array',
            items: { type: 'string' },
          },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      hardcodedString: 'Hardcoded string "{{text}}" should use translation function like t("{{key}}")',
      missingTranslationFunction: 'String "{{text}}" appears to be user-facing but not wrapped in translation function',
      suggestTranslationKey: 'Consider using t("{{suggestedKey}}") for "{{text}}"',
    },
  },

  create(context: Rule.RuleContext): Rule.RuleListener {
    const options = context.options[0] || {};
    const ignorePatterns = (options.ignorePatterns || []).map((p: string) => new RegExp(p));
    const translationFunctions = options.translationFunctions || TRANSLATION_FUNCTIONS;
    const allowedComponents = options.allowedComponents || COMPONENT_EXCEPTIONS;

    function isAllowedString(text: string): boolean {
      // Check if string matches allowed patterns
      return ALLOWED_HARDCODED_PATTERNS.some(pattern => pattern.test(text)) ||
             ignorePatterns.some((pattern: RegExp) => pattern.test(text));
    }

    function isInAllowedContext(node: unknown): boolean {
      const n = node as { parent?: unknown };
      let parent = n.parent as Record<string, unknown> | undefined;

      while (parent) {
        // Skip if inside translation function call
        if (parent && parent['type'] === 'CallExpression' && 
            (parent['callee'] as Record<string, unknown>)?.['name'] && 
            translationFunctions.includes(((parent['callee'] as Record<string, unknown>)['name'] as string))) {
          return true;
        }

        // Skip if inside allowed component props
        if (parent && parent['type'] === 'JSXAttribute' && 
            (parent['name'] as Record<string, unknown>)?.['name'] && 
            allowedComponents.includes(((parent['name'] as Record<string, unknown>)['name'] as string))) {
          return true;
        }

        // Skip if inside console statements
        if (parent && parent['type'] === 'CallExpression' && 
            (parent['callee'] as Record<string, unknown>)?.['object'] && 
            ((parent['callee'] as Record<string, unknown>)['object'] as Record<string, unknown>)?.['name'] === 'console') {
          return true;
        }

        parent = parent && (parent['parent'] as Record<string, unknown> | undefined);
      }

      return false;
    }

    function generateTranslationKey(text: string): string {
      return text
        .toLowerCase()
        .replace(/[^a-z0-9\s]/g, '')
        .replace(/\s+/g, '.')
        .replace(/^\.+|\.+$/g, '')
        .substring(0, 50);
    }

    function checkStringLiteral(node: unknown) {
      const n = node as { type?: string; value?: unknown };
      if (n.type !== 'Literal') return;
      if (typeof n.value !== 'string') return;

      const text = n.value;

      // Skip empty strings or single characters
      if (text.length <= 1) return;

      // Skip allowed strings
      if (isAllowedString(text)) return;

      // Skip if in allowed context
      if (isInAllowedContext(node)) return;

      // Only flag strings that look like user-facing text
      if (!/[a-zA-Z]/.test(text)) return;

      const suggestedKey = generateTranslationKey(text);

      context.report({
        node: node as unknown as Rule.Node,
        messageId: 'hardcodedString',
        data: {
          text: text.substring(0, 50) + (text.length > 50 ? '...' : ''),
          key: suggestedKey,
        },
        fix(fixer) {
          return fixer.replaceText(node as unknown as Rule.Node, `t("${suggestedKey}")`);
        },
      });
    }

    function checkJSXText(node: unknown) {
      const n = node as { type?: string; value?: string };
      if (n.type !== 'JSXText') return;
      const text = (n.value || '').trim();

      if (text.length <= 1) return;
      if (isAllowedString(text)) return;
      if (!/[a-zA-Z]/.test(text)) return;

      const suggestedKey = generateTranslationKey(text);

      context.report({
        node: node as unknown as Rule.Node,
        messageId: 'hardcodedString',
        data: {
          text: text.substring(0, 50) + (text.length > 50 ? '...' : ''),
          key: suggestedKey,
        },
        fix(fixer) {
          return fixer.replaceText(node as unknown as Rule.Node, `{t("${suggestedKey}")}`);
        },
      });
    }

    return {
      Literal: checkStringLiteral,
      JSXText: checkJSXText,
    };
  },
};

const requireTranslationKeys: Rule.RuleModule = {
  meta: {
    type: 'problem',
    docs: {
      description: 'Ensure translation keys exist in translation files',
      category: 'Internationalization',
      recommended: true,
    },
    schema: [],
    messages: {
      missingTranslationKey: 'Translation key "{{key}}" not found in translation files',
      invalidTranslationKey: 'Translation key "{{key}}" format is invalid',
    },
  },

  create(context: Rule.RuleContext): Rule.RuleListener {
    function checkTranslationCall(node: unknown) {
      const n = node as { type?: string; callee?: unknown; arguments?: unknown[] };
      if (n.type !== 'CallExpression') return;
      if (!n.callee || 
          (((n.callee as Record<string, unknown>)['type'] as string) !== 'Identifier' || !TRANSLATION_FUNCTIONS.includes(((n.callee as Record<string, unknown>)['name'] as string)))) {
        return;
      }

      const firstArg = (n.arguments || [])[0] as { type: string; value?: unknown } | undefined;
      if (!firstArg || firstArg.type !== 'Literal' || typeof firstArg.value !== 'string') {
        return;
      }

      const key = firstArg.value;

      // Validate key format
      if (!/^[a-z][a-zA-Z0-9.]*$/.test(key)) {
        context.report({
          node: firstArg as unknown as Rule.Node,
          messageId: 'invalidTranslationKey',
          data: { key },
        });
        return;
      }

      // Check if key exists in translations (would require loading translation files)
      // This is a simplified check - in real implementation, we'd load the actual translation files
      if (key.length < 3 || key.split('.').length > 5) {
        context.report({
          node: firstArg as unknown as Rule.Node,
          messageId: 'missingTranslationKey',
          data: { key },
        });
      }
    }

    return {
      CallExpression: checkTranslationCall,
    };
  },
};

const translationBestPractices: Rule.RuleModule = {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Enforce translation best practices',
      category: 'Internationalization',
      recommended: true,
    },
    schema: [],
    messages: {
      avoidStringConcatenation: 'Avoid string concatenation in translations. Use template parameters instead.',
      useSemanticKeys: 'Use semantic translation keys instead of generic ones like "text1", "label2"',
      consistentKeyFormat: 'Translation keys should follow consistent format: domain.context.element',
    },
  },

  create(context: Rule.RuleContext): Rule.RuleListener {
    function checkTranslationCall(node: unknown) {
      const n = node as { type?: string; callee?: unknown; arguments?: unknown[] };
      if (n.type !== 'CallExpression') return;
      if (!n.callee || 
          (((n.callee as Record<string, unknown>)['type'] as string) !== 'Identifier' || !TRANSLATION_FUNCTIONS.includes(((n.callee as Record<string, unknown>)['name'] as string)))) {
        return;
      }

      const firstArg = (n.arguments || [])[0] as { type: string; value?: unknown } | undefined;
      if (!firstArg || firstArg.type !== 'Literal' || typeof firstArg.value !== 'string') {
        return;
      }

      const key = firstArg.value;

      // Check for generic/non-semantic keys
      if (/^(text|label|title|button|link)\d+$/.test(key)) {
        context.report({
          node: firstArg as unknown as Rule.Node,
          messageId: 'useSemanticKeys',
        });
      }

      // Check for consistent key format
      const parts = key.split('.');
      if (parts.length < 2) {
        context.report({
          node: firstArg as unknown as Rule.Node,
          messageId: 'consistentKeyFormat',
        });
      }
    }

    return {
      CallExpression: checkTranslationCall,
    };
  },
};

// Export the plugin
const plugin: EslintPluginTranslations = {
  rules: {
    'no-hardcoded-strings': noHardcodedStrings,
    'require-translation-keys': requireTranslationKeys,
    'translation-best-practices': translationBestPractices,
  },
  configs: {
    recommended: {
      plugins: ['@translations'],
      rules: {
        '@translations/no-hardcoded-strings': 'error',
        '@translations/require-translation-keys': 'warn',
        '@translations/translation-best-practices': 'warn',
      },
    },
    strict: {
      plugins: ['@translations'],
      rules: {
        '@translations/no-hardcoded-strings': 'error',
        '@translations/require-translation-keys': 'error',
        '@translations/translation-best-practices': 'error',
      },
    },
  },
};

export default plugin;

