                    </AlertDialogHeader>
                    <AlertDialogFooter>
                      <AlertDialogCancel>Annuler</AlertDialogCancel>
                      <AlertDialogAction
                        className="bg-red-600 hover:bg-red-700"
                        onClick={() => handleAction(booking.id, 'cancelled')}
                      >
                        Refuser
                      </AlertDialogAction>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              </>
            )}

            {isVendor && booking.status === 'confirmed' && (
              <Button
                size="sm"
                variant="outline"
                className="gap-1"
                onClick={() => handleAction(booking.id, 'completed')}
                disabled={actionLoading}
              >
                <CheckCircle2 className="h-3.5 w-3.5" /> Marquer termin├®e
              </Button>
            )}

            {!isVendor && booking.status === 'pending' && (
              <AlertDialog>
                <AlertDialogTrigger asChild>
                  <Button size="sm" variant="outline" className="gap-1 text-red-600">
                    <XCircle className="h-3.5 w-3.5" /> Annuler
                  </Button>
                </AlertDialogTrigger>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Annuler cette r├®servation ?</AlertDialogTitle>
                    <AlertDialogDescription>
                      Cette action ne peut pas ├¬tre annul├®e.
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Non</AlertDialogCancel>
                    <AlertDialogAction
                      className="bg-red-600 hover:bg-red-700"
                      onClick={() => handleAction(booking.id, 'cancelled')}
                    >
                      Oui, annuler
                    </AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            )}

            {!isVendor && (
              <Button
                size="sm"
                variant="ghost"
                className="gap-1 text-xs ml-auto"
                onClick={() => window.location.href = getLocalizedPath(`/annonce/${booking.announcement_id}`)}
              >
                Voir l'annonce <ChevronRight className="h-3 w-3" />
              </Button>
            )}
          </div>
        </div>
      </div>
    </Card>
  );

  const EmptyState = ({ message }: { message: string }) => (
    <div className="text-center py-16">
      <Inbox className="h-16 w-16 mx-auto mb-4 text-muted-foreground opacity-30" />
      <p className="text-muted-foreground">{message}</p>
    </div>
  );

  const LoadingState = () => (
    <div className="flex justify-center py-16">
      <Loader2 className="h-8 w-8 animate-spin text-primary" />
    </div>
  );

  return (
    <div className="min-h-screen bg-background py-6">
      <div className="container mx-auto px-4 max-w-3xl">
        {/* Header */}
        <div className="flex items-center gap-3 mb-6">
          <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
            <Calendar className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h1 className="text-xl font-bold">Mes r├®servations</h1>
            <p className="text-sm text-muted-foreground">G├®rez vos rendez-vous et cr├®neaux</p>
