    };
    return map[normalized] || trimmed;
  }

  if (kind === 'packaging') {
    const map: Record<string, string> = {
      avec_boite: 'avec_boite',
      with_box: 'avec_boite',
      sans_boite: 'sans_boite',
      without_box: 'sans_boite',
      boite_origine: 'boite_origine',
      original_box: 'boite_origine',
      scelle: 'scelle',
      sealed: 'scelle',
    };
    return map[normalized] || trimmed;
  }

  if (kind === 'accessory' || kind === 'equipment') {
    const map: Record<string, string> = {
      chargeur: 'chargeur',
      charger: 'chargeur',
      cable: 'cable',
      ecouteurs: 'ecouteurs',
      headphones: 'headphones',
      telecommande: 'telecommande',
      remote: 'telecommande',
      batterie: 'batterie',
      battery: 'batterie',
      coque: 'coque',
      case: 'coque',
      housse: 'housse',
      facture: 'facture',
      invoice: 'facture',
      garantie: 'garantie',
      warranty: 'garantie',
      manuel: 'manuel',
      manual: 'manuel',
    };
    return map[normalized] || trimmed;
  }

  return trimmed;
};

const normalizeFreeValueArray = (
  values: string[] = [],
  kind?: 'accessory' | 'equipment'
) => values.map((value) => normalizeFreeValue(value, kind)).filter(Boolean);

