                                  <div className="absolute top-2 left-2 bg-purple-600 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-md shadow-lg z-10 uppercase tracking-wider">
                                    {t('createAd.mainImage') || 'Principal'}
