        const { error: uploadError } = await supabase.storage
          .from(bucket)
          .upload(filePath, file);

        if (uploadError) {
          logger.error(`Error uploading file to ${bucket}:`, uploadError);
          toast({
             title: t('common.error'),
             description: `${t('createShop.uploadError')}: ${uploadError.message}`,
             variant: "destructive"
          });
          throw uploadError;
