                    </Badge>
                  )}
                  {offer.home_service && (
                    <Badge variant="outline" className="gap-1 border-green-200 bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300">
                      <Truck className="h-3 w-3" />
                      {t('jobOffer.homeVisit')}
