import React, { useState, useEffect, useCallback } from 'react';
import { useSafeI18nWithRouter } from '@/lib/i18n/i18nContextWithRouter';
import { useAuth } from '@/contexts/useAuth';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import {
  Briefcase,
  Clock,
  User,
  Mail,
  Phone,
  Calendar,
  CheckCircle,
  AlertCircle,
  Edit,
  Eye,
  EyeOff
} from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';
import { logger } from '@/utils/silentLogger';
import { useLanguageFromURL } from '@/hooks/useLanguageFromURL';

// Define JobOffer type based on the new table
interface JobOffer {
  id: string;
  user_id: string;
  title: string;
  description: string | null;
  profession: string;
  specialty: string | null;
  phone_numbers: string[] | null;
  email: string | null;
  wilaya: string | null;
  commune: string | null;
  location: string | null;
  created_at: string;
  is_active: boolean;
  expires_at: string | null;
}

import AuthRequiredBubble from '@/components/auth/AuthRequiredBubble';

const JobOfferMessages = () => {
  const { t, isRTL } = useSafeI18nWithRouter();
  const { user } = useAuth();
  const { toast } = useToast();
  const { getLocalizedPath } = useLanguageFromURL();
  const [offers, setOffers] = useState<JobOffer[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedOffer, setSelectedOffer] = useState<JobOffer | null>(null);
  const [filter, setFilter] = useState<'all' | 'active' | 'inactive'>('all');

  const fetchOffers = useCallback(async () => {
    if (!user) return;

    setLoading(true);
    try {
      let query: any = supabase
        .from('professional_job_offers')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (filter === 'active') {
        query = query.eq('is_active', true);
      } else if (filter === 'inactive') {
        query = query.eq('is_active', false);
      }

      const { data, error } = await query;

      if (error) throw error;
      setOffers((data as JobOffer[]) ?? []);
    } catch (error) {
      logger.error('Error fetching job offers:', error);
      toast({
        title: t('common.error'),
        description: t('jobOfferMessages.loadError'),
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [user, filter, toast]);

  useEffect(() => {
    fetchOffers();
  }, [fetchOffers]);

  const toggleActiveStatus = async (offerId: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('professional_job_offers')
        .update({ is_active: !currentStatus })
        .eq('id', offerId);

      if (error) throw error;

      setOffers(prev =>
        prev.map(offer =>
          offer.id === offerId ? { ...offer, is_active: !currentStatus } : offer
        )
      );

      if (selectedOffer?.id === offerId) {
        setSelectedOffer(prev => prev ? { ...prev, is_active: !currentStatus } : null);
      }

      toast({
        title: t('jobOfferMessages.statusUpdated'),
        description: !currentStatus ? t('jobOfferMessages.activated') : t('jobOfferMessages.deactivated'),
      });
    } catch (error) {
      logger.error('Error updating offer status:', error);
      toast({
        title: t('common.error'),
        description: t('jobOfferMessages.statusError'),
        variant: "destructive",
      });
    }
  };

  const activeCount = offers.filter(offer => offer.is_active).length;

  if (!user) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <AuthRequiredBubble 
          message={t('jobOfferMessages.loginRequired')}
          className="max-w-md w-full"
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background py-8" dir={isRTL ? 'rtl' : 'ltr'}>
      <div className="container mx-auto px-4">
        <div className="max-w-7xl mx-auto">
          {/* Header */}
          <Card className="mb-6">
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Briefcase className="h-8 w-8 text-primary" />
                  <div>
                    <CardTitle className="text-2xl">{t('jobOfferMessages.title')}</CardTitle>
                    <CardDescription>
                      {t('jobOfferMessages.description')}
                    </CardDescription>
                  </div>
                </div>
                {activeCount > 0 && (
                  <Badge variant="default" className="text-sm">
                    {activeCount} active{activeCount > 1 ? 's' : ''}
                  </Badge>
                )}
              </div>
            </CardHeader>
          </Card>

          {/* Filtres */}
          <Card className="mb-6">
            <CardContent className="pt-6">
              <div className="flex flex-wrap gap-2">
                <Button
                  variant={filter === 'all' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setFilter('all')}
                >
                  {t('jobOfferMessages.allOffers')}
                </Button>
                <Button
                  variant={filter === 'active' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setFilter('active')}
                >
                  {t('jobOfferMessages.activeOffers')} {activeCount > 0 && `(${activeCount})`}
                </Button>
                <Button
                  variant={filter === 'inactive' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setFilter('inactive')}
                >
                  {t('jobOfferMessages.inactiveOffers')}
                </Button>
              </div>
            </CardContent>
          </Card>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Liste des offres */}
            <div className="lg:col-span-1">
              <Card className="h-[600px]">
                <CardHeader>
                  <CardTitle className="text-lg">
                    {filter === 'active' ? 'Offres actives' :
                     filter === 'inactive' ? 'Offres inactives' :
                     'Toutes les offres'}
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="h-[500px] overflow-y-auto">
                    {loading ? (
                      <div className="flex items-center justify-center h-32">
                        <div className="text-sm text-muted-foreground">{t('jobOfferMessages.loading')}</div>
                      </div>
                    ) : offers.length === 0 ? (
                      <div className="flex items-center justify-center h-32">
                        <div className="text-center">
                          <Briefcase className="h-12 w-12 mx-auto mb-2 text-muted-foreground" />
                          <div className="text-sm text-muted-foreground">
                            {filter === 'active' ? t('jobOfferMessages.noActiveOffer') :
                             filter === 'inactive' ? t('jobOfferMessages.noInactiveOffer') :
                             t('jobOfferMessages.noOffer')}
                          </div>
                        </div>
                      </div>
                    ) : (
                      <div className="divide-y">
                        {offers.map((offer) => (
                          <div
                            key={offer.id}
                            className={`p-4 cursor-pointer hover:bg-muted/50 transition-colors ${
                              selectedOffer?.id === offer.id ? 'bg-muted/50' : ''
                            } ${offer.is_active ? 'border-l-4 border-green-500' : 'border-l-4 border-gray-300'}`}
                            onClick={() => setSelectedOffer(offer)}
                          >
                            <div className="flex items-start justify-between gap-2">
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 mb-1">
                                  <Briefcase className="h-4 w-4 text-muted-foreground" />
                                  <span className="font-medium text-sm truncate">
                                    {offer.title}
                                  </span>
                                  {offer.is_active ? (
                                    <Badge variant="default" className="text-xs">
                                      <Eye className="h-3 w-3 mr-1" />
                                      {t('jobOfferMessages.active')}
                                    </Badge>
                                  ) : (
                                    <Badge variant="secondary" className="text-xs">
                                      <EyeOff className="h-3 w-3 mr-1" />
                                      {t('jobOfferMessages.inactive')}
                                    </Badge>
                                  )}
                                </div>
                                <div className="text-xs text-muted-foreground mb-1">
                                  {offer.profession} {offer.specialty && `- ${offer.specialty}`}
                                </div>
                                <div className="text-sm text-muted-foreground truncate">
                                  {offer.description}
                                </div>
                                <div className="flex items-center gap-1 mt-1">
                                  <Clock className="h-3 w-3 text-muted-foreground" />
                                  <span className="text-xs text-muted-foreground">
                                    {formatDistanceToNow(new Date(offer.created_at), {
                                      addSuffix: true,
                                      locale: fr
                                    })}
                                  </span>
                                </div>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* D├®tails de l'offre */}
            <div className="lg:col-span-2">
              {selectedOffer ? (
                <Card className="h-[600px]">
                  <CardHeader>
                    <div className="flex items-start justify-between">
                      <div>
                        <CardTitle className="flex items-center gap-2">
                          <Briefcase className="h-5 w-5 text-primary" />
                          {selectedOffer.title}
                        </CardTitle>
                        <CardDescription>
                          {t('jobOfferMessages.createdOn')} {new Date(selectedOffer.created_at).toLocaleDateString()}
                        </CardDescription>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          variant={selectedOffer.is_active ? "destructive" : "default"}
                          size="sm"
                          onClick={() => toggleActiveStatus(selectedOffer.id, selectedOffer.is_active)}
                        >
                          {selectedOffer.is_active ? (
                            <>
                              <EyeOff className="h-4 w-4 mr-1" />
                              {t('jobOfferMessages.deactivate')}
                            </>
                          ) : (
                            <>
                              <Eye className="h-4 w-4 mr-1" />
                              {t('jobOfferMessages.activate')}
                            </>
                          )}
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => {
                            const phone =
                              selectedOffer.phone_numbers && selectedOffer.phone_numbers.length > 0
                                ? selectedOffer.phone_numbers[0]
                                : '';
                            if (phone) window.open(`tel:${phone}`);
                          }}
                          disabled={!selectedOffer.phone_numbers || selectedOffer.phone_numbers.length === 0}
                        >
                          <Phone className="h-4 w-4 mr-1" />
                          {t('jobOfferMessages.contact')}
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="flex items-center gap-2">
                        <User className="h-4 w-4 text-muted-foreground" />
                        <span className="text-sm font-medium">{t('jobOfferMessages.titleLabel')}</span>
                        <span className="text-sm">{selectedOffer.title}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Mail className="h-4 w-4 text-muted-foreground" />
                        <span className="text-sm font-medium">{t('jobOfferMessages.contactLabel')}</span>
                        {selectedOffer.phone_numbers && selectedOffer.phone_numbers.length > 0 ? (
                          <a
                            href={`tel:${selectedOffer.phone_numbers[0]}`}
                            className="text-sm text-primary hover:underline"
                          >
                            {selectedOffer.phone_numbers[0]}
                          </a>
                        ) : (
                          <span className="text-sm text-muted-foreground">-</span>
                        )}
                      </div>
                      <div className="flex items-center gap-2">
                        <Calendar className="h-4 w-4 text-muted-foreground" />
                        <span className="text-sm font-medium">{t('jobOfferMessages.createdOnLabel')}</span>
                        <span className="text-sm">
                          {new Date(selectedOffer.created_at).toLocaleDateString('fr-FR', {
                            day: 'numeric',
                            month: 'long',
                            year: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </span>
                      </div>
                      {selectedOffer.expires_at && (
                        <div className="flex items-center gap-2">
                          <Clock className="h-4 w-4 text-muted-foreground" />
                          <span className="text-sm font-medium">{t('jobOfferMessages.expiresOnLabel')}</span>
                          <span className="text-sm">
                            {new Date(selectedOffer.expires_at).toLocaleDateString('fr-FR', {
                              day: 'numeric',
                              month: 'long',
                              year: 'numeric'
                            })}
                          </span>
                        </div>
                      )}
                    </div>

                    <Separator />

                    <div>
                      <h4 className="text-sm font-medium mb-2">{t('jobOfferMessages.descriptionLabel')}</h4>
                      <div className="p-4 bg-muted/30 rounded-lg">
                        <p className="text-sm whitespace-pre-wrap">
                          {selectedOffer.description}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 pt-4">
                      {selectedOffer.is_active ? (
                        <Badge variant="default" className="text-xs">
                          <CheckCircle className="h-3 w-3 mr-1" />
                          {t('jobOfferMessages.offerActive')}
                        </Badge>
                      ) : (
                        <Badge variant="secondary" className="text-xs">
                          <AlertCircle className="h-3 w-3 mr-1" />
                          {t('jobOfferMessages.offerInactive')}
                        </Badge>
                      )}
                    </div>

                    <div className="flex gap-2 pt-4">
                      <Button
                        onClick={() => {
                          const phone = selectedOffer.phone_numbers && selectedOffer.phone_numbers.length > 0 ? selectedOffer.phone_numbers[0] : '';
                          if (phone) window.open(`tel:${phone}`);
                        }}
                        className="flex-1"
                        disabled={!selectedOffer.phone_numbers || selectedOffer.phone_numbers.length === 0}
                      >
                        <Phone className="h-4 w-4 mr-2" />
                        {t('jobOfferMessages.contactByPhone')}
                      </Button>
                      <Button
                        variant="outline"
                        onClick={() => window.open(getLocalizedPath('/deposer-offre-metier'))}
                      >
                        <Edit className="h-4 w-4 mr-2" />
                        {t('jobOfferMessages.edit')}
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ) : (
                <Card className="h-[600px] flex items-center justify-center">
                  <CardContent className="text-center">
                    <Briefcase className="h-16 w-16 mx-auto mb-4 text-muted-foreground" />
                    <h3 className="text-xl font-semibold mb-2">
                      {t('jobOfferMessages.selectOffer')}
                    </h3>
                    <p className="text-muted-foreground">
                      {t('jobOfferMessages.selectOfferDesc')}
                    </p>
                  </CardContent>
                </Card>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

