import { useLanguageNavigation } from '@/hooks/useLanguageNavigation';

type Favorite = {
  id: string; // favorite id
  announcement: {
    id: string;
    title: string;
    price: number;
    category_id: string;
    category_slug?: string | null;
    wilaya: string;
    location: string | null;
    is_urgent: boolean;
    is_pro?: boolean; // inferred or added later
    created_at: string;
    images: string[] | null;
    image_url: string | null;
    image_urls: string[] | null;
    currency: string;
  };
};

const MesFavoris = () => {
  const { t, language } = useSafeI18nWithRouter();
  const [searchQuery, setSearchQuery] = useState('');
  const [favorites, setFavorites] = useState<Favorite[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { getLocalizedPath } = useLanguageNavigation();
  const { data: categoriesFromSupabase = [] } = useCategories(language);
  const menuCategories = mergeOfficialAndSupabaseCategories(language, categoriesFromSupabase);

  const tr = (key: string, fallback: string | Record<string, string>) => {
    const translated = t(key);
    if (translated && translated !== key) return translated;
    if (typeof fallback === 'string') return fallback;
    return fallback[language] || fallback.fr || Object.values(fallback)[0] || key;
  };

  useEffect(() => {
    const fetchFavorites = async () => {
      if (!user) {
        setLoading(false);
        return;
      }

      try {
        const { data, error } = await supabase
          .from('announcement_favorites')
          .select(`
            id,
            announcement:announcements (
              id,
              title,
              price,
              category_id,
              category_slug,
              wilaya,
              location,
              is_urgent,
              created_at,
              images,
              image_url,
              image_urls,
              currency
            )
          `)
          .eq('user_id', user.id)
          .order('created_at', { ascending: false });

        if (error) throw error;

        // Filter out favorites where announcement might be null (deleted)
        const validFavorites = (data || []).filter(f => f.announcement) as Favorite[];
        setFavorites(validFavorites);
      } catch (error) {
        logger.error('Error fetching favorites:', error);
        toast({
          title: t('common.error'),
          description: tr('mesFavoris.errorLoading', {
            fr: 'Impossible de charger vos favoris',
            en: 'Unable to load your favorites',
            es: 'No se pudieron cargar tus favoritos',
            it: 'Impossibile caricare i tuoi preferiti',
            de: 'Ihre Favoriten konnten nicht geladen werden',
            ar: 'Ï¬Ï╣Ï░Ï▒ Ï¬Ï¡┘à┘è┘ä Ïº┘ä┘à┘üÏÂ┘äÏ®',
          }),
          variant: "destructive"
        });
      } finally {
        setLoading(false);
      }
    };

    fetchFavorites();
  }, [user, toast]);

  const filteredFavorites = favorites.filter(fav =>
    fav.announcement.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    fav.announcement.wilaya?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    fav.announcement.location?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleRemoveFavorite = async (id: string) => {
    try {
      const { error } = await supabase
        .from('announcement_favorites')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setFavorites(prev => prev.filter(f => f.id !== id));
      toast({
        title: t('common.success'),
        description: tr('mesFavoris.favoriteRemoved', {
          fr: 'Favori supprim├®',
          en: 'Favorite removed',
          es: 'Favorito eliminado',
          it: 'Preferito rimosso',
          de: 'Favorit entfernt',
          ar: 'Ï¬┘àÏ¬ ÏÑÏ▓Ïº┘äÏ® Ïº┘ä┘à┘üÏÂ┘äÏ®',
        })
      });
    } catch (error) {
      logger.error('Error removing favorite:', error);
      toast({
        title: t('common.error'),
        description: tr('mesFavoris.errorRemovingFavorite', {
          fr: 'Impossible de supprimer le favori',
          en: 'Unable to remove the favorite',
          es: 'No se pudo eliminar el favorito',
          it: 'Impossibile rimuovere il preferito',
          de: 'Favorit konnte nicht entfernt werden',
          ar: 'Ï¬Ï╣Ï░Ï▒ ÏÑÏ▓Ïº┘äÏ® Ïº┘ä┘à┘üÏÂ┘äÏ®',
        }),
        variant: "destructive"
      });
    }
  };

  const FavoriteCard = ({ favorite }: { favorite: Favorite }) => {
    const ann = favorite.announcement;
    const imageUrl = ann.images && ann.images.length > 0 ? ann.images[0] : '/placeholder.png';
    const location = ann.wilaya || ann.location || t('mesFavoris.locationNotSpecified');
    const categoryLookupKey = ann.category_slug || ann.category_id;
    const categoryFromMenu = menuCategories.find((cat) => cat.slug === categoryLookupKey || cat.id === categoryLookupKey);
    const translationKey = `categories.${categoryLookupKey}`;
    const translatedCategory = t(translationKey);
    const categoryLabel =
      categoryFromMenu?.name ||
      (translatedCategory !== translationKey && !translatedCategory.startsWith('categories.') ? translatedCategory : '') ||
      t('createAd.category') ||
      tr('createAd.category', {
        fr: 'Cat├®gorie',
        en: 'Category',
        es: 'Categor├¡a',
        it: 'Categoria',
        de: 'Kategorie',
        ar: 'Ïº┘ä┘üÏªÏ®',
      });

    return (
    <Card className="hover:shadow-md transition-shadow">
      <CardContent className="p-4">
        <div className="flex gap-4">
          <div className="relative">
            <img
              src={imageUrl}
              alt={ann.title}
              className="w-32 h-32 object-cover rounded-lg"
            />
            {ann.is_urgent && (
              <Badge className="absolute top-2 left-2 bg-red-500 text-white text-xs">
                {t('mesFavoris.urgent')}
              </Badge>
            )}
            {/* isPro check can be added if available in data */}
          </div>
          <div className="flex-1">
            <div className="flex items-start justify-between mb-2">
              <h3 className="font-semibold text-lg line-clamp-2">{ann.title}</h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleRemoveFavorite(favorite.id)}
                className="text-red-500 hover:text-red-700"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
            <p className="text-2xl font-bold text-primary mb-2">
              {ann.price ? `${ann.price.toLocaleString()} ${ann.currency || 'DA'}` : t('mesFavoris.priceNotSpecified')}
            </p>
            <div className="flex items-center gap-2 mb-3">
              <Badge variant="outline">{categoryLabel}</Badge>
              <span className="text-sm text-muted-foreground">{location}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-gray-500">
                {t('mesFavoris.addedOn')} {new Date(ann.created_at).toLocaleDateString()}
              </span>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={() => navigate(getLocalizedPath(`/announcement/${ann.id}`))}>
                  <Eye className="h-4 w-4 mr-1" />
                  {t('mesFavoris.view')}
                </Button>
                <Button variant="outline" size="sm" onClick={() => navigate(getLocalizedPath(`/announcement/${ann.id}`))}>
                  <MessageCircle className="h-4 w-4 mr-1" />
                  {t('mesFavoris.contact')}
                </Button>
                <Button variant="outline" size="sm">
                  <Share2 className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 py-12">
      <div className="container mx-auto px-4">
        <div className="max-w-6xl mx-auto">
          <Card className="mb-6">
            <CardHeader>
              <div className="flex items-center gap-3">
                <Heart className="h-8 w-8 text-red-500" />
                <div>
                  <CardTitle className="text-2xl">{t('mesFavoris.title')}</CardTitle>
                  <CardDescription>{t('mesFavoris.subtitle')}</CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between mb-4">
                <div className="relative flex-1 max-w-md">
                  <Search className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                  <Input
                    placeholder={t('mesFavoris.searchPlaceholder')}
                    value={searchQuery}
                    onChange={(event) => setSearchQuery(event.target.value)}
                    className="pl-10"
                  />
                </div>
                <div className="text-sm text-gray-600">
                  {filteredFavorites.length} {t('mesFavoris.results')}
                </div>
              </div>
            </CardContent>
          </Card>

          <div className="space-y-4">
            {filteredFavorites.length > 0 ? (
              filteredFavorites.map(favorite => (
                <FavoriteCard key={favorite.id} favorite={favorite} />
              ))
            ) : (
              <div className="text-center py-16">
                <Heart className="h-16 w-16 mx-auto mb-4 text-gray-400" />
                <h3 className="text-xl font-semibold mb-2">{t('mesFavoris.noFavorites')}</h3>
                <p className="text-gray-600 mb-6 max-w-md mx-auto">
                  {t('mesFavoris.noFavoritesDesc')}
                </p>
                <Button>
                  {t('mesFavoris.browseAds')}
                </Button>
              </div>
            )}
          </div>

          {filteredFavorites.length > 0 && (
            <div className="mt-8 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
              <div className="flex items-center gap-3">
                <Heart className="h-5 w-5 text-blue-600" />
                <div>
                  <h4 className="font-medium text-blue-900 dark:text-blue-100">
                    {t('mesFavoris.tip')}
                  </h4>
                  <p className="text-sm text-blue-700 dark:text-blue-200">
                    {t('mesFavoris.tipDesc')}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default MesFavoris;

import { useState, useEffect } from 'react';
import { useSafeI18nWithRouter  } from "@/lib/i18n/i18nContextWithRouter";
import { useAuth } from '@/contexts/useAuth';
import { MessageCircle, Loader2, FileText, ShoppingBag, Briefcase, ArrowLeft } from 'lucide-react';
import ConversationList from '@/components/messaging/ConversationList';
import MessageThread from '@/components/messaging/MessageThread';
import { useSearchParams, Link } from 'react-router-dom';
import { supabase } from '@/integrations/supabase/client';
import { logger } from '@/utils/silentLogger';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { useLanguageNavigation } from '@/hooks/useLanguageNavigation';

const Messages = () => {
  const { t, language } = useSafeI18nWithRouter();
  const { user } = useAuth();
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [searchParams, setSearchParams] = useSearchParams();
  const [initializing, setInitializing] = useState(false);
  const [activeFilter, setActiveFilter] = useState<'all' | 'ad' | 'shop' | 'job_offer'>('all');
  const { getLocalizedPath } = useLanguageNavigation();

  // Use `t` for translations
  const translate = t;

  const tr = (key: string, fallback: string | Record<string, string>) => {
    const translated = t(key);
    if (translated && translated !== key) return translated;
    if (typeof fallback === 'string') return fallback;
    return fallback[language] || fallback.fr || Object.values(fallback)[0] || key;
  };

  const handleTabClick = (filter: 'all' | 'ad' | 'shop' | 'job_offer') => {
    setActiveFilter(filter);
    setSelectedConversationId(null);
  };

  // Handle URL parameters for starting new conversations
  useEffect(() => {
    const initConversation = async () => {
      if (!user) return;

      const announcementId = searchParams.get('announcement');
      const shopId = searchParams.get('shop');
      const jobOfferId = searchParams.get('job_offer');
      const conversationId = searchParams.get('conversation');

      if (conversationId) {
        setSelectedConversationId(conversationId);
        return;
      }

      if (!announcementId && !shopId && !jobOfferId) return;

      setInitializing(true);
      try {
        let subjectType: 'ad' | 'shop' | 'job_offer' | null = null;
        let subjectId: string | null = null;
        let ownerId: string | null = null;
        let title: string | null = null;

        if (announcementId) {
          subjectType = 'ad';
          subjectId = announcementId;
          const { data } = await supabase.from('announcements').select('user_id, title').eq('id', announcementId).single();
          if (data) {
             ownerId = data.user_id;
             title = data.title;
          }
        } else if (shopId) {
          subjectType = 'shop';
          subjectId = shopId;
          // Note: Adjust table name/columns if different
          const { data } = await supabase.from('shops').select('user_id, name').eq('id', shopId).single(); 
          if (data) {
             ownerId = data.user_id;
             title = data.name;
          }
        } else if (jobOfferId) {
           subjectType = 'job_offer';
           subjectId = jobOfferId;
           // Note: Adjust table name/columns if different
           const { data } = await supabase.from('professional_job_offers').select('user_id, title').eq('id', jobOfferId).single();
           if (data) {
              ownerId = data.user_id;
              title = data.title;
           }
        }

        if (ownerId && ownerId !== user.id) {
           // Check if conversation exists
           // We use a broader check first to find ANY conversation with this subject between these users
           const { data: existing } = await supabase
             .from('conversations')
             .select('id')
             .or(`and(participant_1_id.eq.${user.id},participant_2_id.eq.${ownerId}),and(participant_1_id.eq.${ownerId},participant_2_id.eq.${user.id})`)
             .eq('subject_type', subjectType)
             .eq('subject_id', subjectId)
             .limit(1)
             .maybeSingle();

           if (existing) {
             setSelectedConversationId(existing.id);
           } else {
             // Create new
             const now = new Date().toISOString();
             const { data: newConv, error } = await supabase
               .from('conversations')
               .insert({
                 participant_1_id: user.id,
                 participant_2_id: ownerId,
                 subject_type: subjectType,
                 subject_id: subjectId,
                title: title || tr('messages.newConversation', {
                  fr: 'Nouvelle conversation',
                  en: 'New conversation',
                  es: 'Nueva conversaci├│n',
                  it: 'Nuova conversazione',
                  de: 'Neue Konversation',
                  ar: '┘àÏ¡ÏºÏ»Ï½Ï® Ï¼Ï»┘èÏ»Ï®',
                }),
                 updated_at: now,
                 last_message_at: now
               })
               .select()
               .single();

             if (newConv) {
               setSelectedConversationId(newConv.id);
             } else if (error) {
               logger.error("Error creating conversation:", error);
             }
           }
        }
      } catch (err) {
        logger.error("Error initializing conversation:", err);
      } finally {
        setInitializing(false);
        // Clear params to avoid re-running
        setSearchParams({});
      }
    };

    initConversation();
  }, [user, searchParams, setSearchParams]);

  if (!user) {
    return (
      <div className="min-h-screen bg-background py-12">
        <div className="container mx-auto px-4">
          <div className="max-w-md mx-auto text-center">
            <MessageCircle className="h-16 w-16 mx-auto mb-4 text-muted-foreground" />
            <h2 className="text-2xl font-bold mb-4">{translate('auth.loginRequired')}</h2>
            <p className="text-muted-foreground">
              {translate('messages.loginRequiredDesc')}
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background py-8">
      <div className="container mx-auto px-4">
        <div className="max-w-7xl mx-auto">
          <div 
            className="mb-6 rounded-[24px] overflow-hidden"
            style={{
              background: 'linear-gradient(145deg, #ffffff, #e6e6e6)',
              boxShadow: '12px 12px 24px #a3a3a3, -12px -12px 24px #ffffff',
              border: '1px solid rgba(255,255,255,0.6)'
            }}
          >
            <div className="dark:bg-slate-800/90 dark:backdrop-blur-sm p-6 relative">
              <Button 
                asChild
                variant="outline" 
                className={cn(
                  "absolute top-1/2 -translate-y-1/2 rounded-xl bg-white/80 dark:bg-slate-800/80 backdrop-blur-sm border-2 border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700 shadow-sm text-slate-700 dark:text-slate-300 transition-all font-semibold hidden md:flex",
                  language === 'ar' ? "left-6" : "right-6"
                )}
              >
                <Link to={getLocalizedPath('/')}>
                  {tr('categories.backToHome', {
                    fr: "Retour ├á l'accueil",
                    en: 'Back to home',
                    es: 'Volver al inicio',
                    it: 'Torna alla home',
                    de: 'Zur Startseite',
                    ar: 'Ïº┘äÏ╣┘êÏ»Ï® ÏÑ┘ä┘ë Ïº┘äÏ▒Ïª┘èÏ│┘èÏ®',
                  })}
                </Link>
              </Button>
              <div className="flex items-center gap-3">
                <div className="p-3 rounded-full bg-primary/10">
                  <MessageCircle className="h-8 w-8 text-primary" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-primary to-purple-600">
                    {translate('messages.title')}
                  </h1>
                  <p className="text-muted-foreground">{translate('messages.subtitle')}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Onglets 3D Bomb├®s de Filtrage (Filter Tabs) */}
          <div className="flex flex-wrap gap-4 mb-8 pb-2 px-2">
            <button
              onClick={() => handleTabClick('all')}
              className={cn(
                "flex-1 min-w-[220px] flex flex-col items-center justify-center gap-2 px-6 py-4 rounded-[20px] transition-all border-2 group",
                activeFilter === 'all' 
                  ? "bg-gradient-to-r from-blue-500 to-cyan-500 text-white border-blue-400 shadow-[inset_0_2px_8px_rgba(255,255,255,0.4),0_12px_24px_-10px_rgba(59,130,246,0.7)] transform -translate-y-1.5" 
                  : "bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 shadow-[0_6px_15px_-5px_rgba(0,0,0,0.1)] hover:shadow-[0_10px_20px_-5px_rgba(59,130,246,0.3)] hover:-translate-y-1 hover:border-blue-300"
              )}
            >
              <div className="flex items-center gap-3">
                <div className={cn("p-2 rounded-xl shadow-inner", activeFilter === 'all' ? "bg-white/20" : "bg-blue-50 dark:bg-blue-900/30 group-hover:bg-blue-100 dark:group-hover:bg-blue-900/50")}>
                  <MessageCircle className={cn("h-6 w-6", activeFilter === 'all' ? "text-white" : "text-blue-500")} />
                </div>
                <span className="text-lg font-extrabold">{tr('messages.tabs.all.title', {
                  fr: 'Toutes les discussions',
                  en: 'All conversations',
                  es: 'Todas las conversaciones',
                  it: 'Tutte le conversazioni',
                  de: 'Alle Gespr├ñche',
                  ar: 'Ï¼┘à┘èÏ╣ Ïº┘ä┘àÏ¡ÏºÏ»Ï½ÏºÏ¬',
                })}</span>
              </div>
              <span className={cn("text-xs font-medium text-center", activeFilter === 'all' ? "text-blue-100" : "text-slate-400")}>
                {tr('messages.tabs.all.desc', {
                  fr: 'G├®rez tous vos ├®changes en un seul endroit',
                  en: 'Manage all your conversations in one place',
                  es: 'Gestiona todas tus conversaciones en un solo lugar',
                  it: 'Gestisci tutte le tue conversazioni in un unico posto',
                  de: 'Verwalten Sie alle Ihre Gespr├ñche an einem Ort',
                  ar: 'ÏúÏ»Ï▒ Ï¼┘à┘èÏ╣ ┘àÏ¡ÏºÏ»Ï½ÏºÏ¬┘â ┘ü┘è ┘à┘âÏº┘å ┘êÏºÏ¡Ï»',
                })}
              </span>
            </button>

            <button
              onClick={() => handleTabClick('ad')}
              className={cn(
                "flex-1 min-w-[220px] flex flex-col items-center justify-center gap-2 px-6 py-4 rounded-[20px] transition-all border-2 group",
                activeFilter === 'ad' 
                  ? "bg-gradient-to-r from-green-600 to-emerald-600 text-white border-green-500 shadow-[inset_0_2px_8px_rgba(255,255,255,0.4),0_12px_24px_-10px_rgba(16,185,129,0.7)] transform -translate-y-1.5" 
                  : "bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 shadow-[0_6px_15px_-5px_rgba(0,0,0,0.1)] hover:shadow-[0_10px_20px_-5px_rgba(16,185,129,0.3)] hover:-translate-y-1 hover:border-green-300"
              )}
            >
              <div className="flex items-center gap-3">
                <div className={cn("p-2 rounded-xl shadow-inner", activeFilter === 'ad' ? "bg-white/20" : "bg-green-50 dark:bg-green-900/30 group-hover:bg-green-100 dark:group-hover:bg-green-900/50")}>
                  <FileText className={cn("h-6 w-6", activeFilter === 'ad' ? "text-white" : "text-green-500")} />
                </div>
                <span className="text-lg font-extrabold">{tr('messages.tabs.ad.title', {
                  fr: 'Annonces',
                  en: 'Listings',
                  es: 'Anuncios',
                  it: 'Annunci',
                  de: 'Anzeigen',
                  ar: 'Ïº┘äÏÑÏ╣┘äÏº┘åÏºÏ¬',
                })}</span>
              </div>
              <span className={cn("text-xs font-medium text-center", activeFilter === 'ad' ? "text-green-100" : "text-slate-400")}>
                {tr('messages.tabs.ad.desc', {
                  fr: "Messages li├®s ├á l'achat ou vente d'articles",
                  en: 'Messages related to buying or selling items',
                  es: 'Mensajes relacionados con la compra o venta de art├¡culos',
                  it: "Messaggi relativi all'acquisto o alla vendita di articoli",
                  de: 'Nachrichten zum Kauf oder Verkauf von Artikeln',
                  ar: 'Ï▒Ï│ÏºÏª┘ä ┘àÏ▒Ï¬Ï¿ÏÀÏ® Ï¿Ï┤Ï▒ÏºÏí Ïú┘ê Ï¿┘èÏ╣ Ïº┘ä┘à┘åÏ¬Ï¼ÏºÏ¬',
                })}
              </span>
            </button>

            <button
              onClick={() => handleTabClick('shop')}
              className={cn(
                "flex-1 min-w-[220px] flex flex-col items-center justify-center gap-2 px-6 py-4 rounded-[20px] transition-all border-2 group",
                activeFilter === 'shop' 
                  ? "bg-gradient-to-r from-purple-600 via-violet-600 to-fuchsia-600 text-white border-purple-500 shadow-[inset_0_2px_8px_rgba(255,255,255,0.4),0_12px_24px_-10px_rgba(139,92,246,0.7)] transform -translate-y-1.5" 
                  : "bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 shadow-[0_6px_15px_-5px_rgba(0,0,0,0.1)] hover:shadow-[0_10px_20px_-5px_rgba(139,92,246,0.3)] hover:-translate-y-1 hover:border-purple-300"
              )}
