    currency?: string;
    location?: string;
    wilaya?: string;
    is_featured?: boolean;
    is_urgent?: boolean;
    is_active?: boolean;
    type?: string;
  }
  const [announcementDetails, setAnnouncementDetails] = useState<AnnouncementDetails | null>(null);
  const [loading, setLoading] = useState(true);

  const sessionId = searchParams.get('session_id');
  const announcementId = searchParams.get('announcement_id');
  const paymentType = searchParams.get('payment_type');
  const mode = searchParams.get('mode') || 'stripe';

  useEffect(() => {
    const verifyAndFetch = async () => {
      try {
        if (mode === 'algerian') {
          if (!announcementId || !paymentType) {
            setLoading(false);
            return;
          }
          const { error: vError } = await supabase.functions.invoke('verify-algerian-payment', {
            body: { announcement_id: announcementId, payment_type: paymentType }
          });
          if (vError) throw vError;
        } else {
          if (!sessionId) {
            setLoading(false);
            return;
          }
          const { error: vError } = await supabase.functions.invoke('verify-payment', {
            body: { session_id: sessionId }
          });
          if (vError) throw vError;
        }

        if (!announcementId) {
          setLoading(false);
          return;
        }

        const { data, error } = await supabase
          .from('announcements')
          .select('*')
          .eq('id', announcementId)
          .single();

        if (error) {
          logger.error('Error fetching announcement:', error);
          toast({
            title: t('common.error'),
            description: t('payment.fetchError'),
            variant: "destructive",
          });
        } else {
          setAnnouncementDetails(data as AnnouncementDetails);
        }
      } catch (error) {
        logger.error('Error:', error);
      } finally {
        setLoading(false);
      }
    };

    verifyAndFetch();
  }, [announcementId, sessionId, paymentType, mode, toast]);

  const getPaymentTypeInfo = () => {
    switch (paymentType) {
      case 'featured':
        return {
          title: t('payment.featured.title'),
          description: t('payment.featured.description'),
          icon: <Star className="h-6 w-6 text-yellow-500" />,
          badge: <Badge variant="default" className="bg-yellow-500">{t('payment.featured.badge')}</Badge>
        };
      case 'urgent':
        return {
          title: t('payment.urgent.title'),
          description: t('payment.urgent.description'),
          icon: <ArrowRight className="h-6 w-6 text-red-500" />,
          badge: <Badge variant="destructive">{t('payment.urgent.badge')}</Badge>
        };
      default:
        return {
          title: t('payment.promotion.title'),
          description: t('payment.promotion.description'),
          icon: <CheckCircle className="h-6 w-6 text-green-500" />,
          badge: <Badge variant="default">{t('payment.promotion.badge')}</Badge>
        };
    }
  };

  const paymentInfo = getPaymentTypeInfo();

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background py-8">
      <div className="container mx-auto px-4 max-w-4xl">
        {/* Success Header */}
        <div className="text-center mb-8">
          <CheckCircle className="h-16 w-16 text-green-500 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-foreground mb-2">
            {t('payment.confirmed')}
          </h1>
          <p className="text-lg text-muted-foreground">
            {t('payment.transactionSuccess')}
          </p>
        </div>

        <div className="grid gap-6 md:grid-cols-2">
          {/* Payment Details */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                {paymentInfo.icon}
                {paymentInfo.title}
              </CardTitle>
              <CardDescription>
                {paymentInfo.description}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {sessionId && (
                <div>
                  <label className="text-sm font-medium text-muted-foreground">
                    {t('payment.transactionId')}
                  </label>
                  <p className="text-sm font-mono bg-muted p-2 rounded">
                    {sessionId}
                  </p>
                </div>
              )}

              <div className="flex items-center gap-2">
                <span className="text-sm font-medium">{t('payment.statusLabel')}</span>
                {paymentInfo.badge}
              </div>

              <div className="pt-4 space-y-2">
                <Button asChild className="w-full">
                  <LocalizedLink to="/my-announcements">
                    <Eye className="h-4 w-4 mr-2" />
                    {t('payment.viewMyAds')}
                  </LocalizedLink>
                </Button>

                <Button variant="outline" asChild className="w-full">
                  <LocalizedLink to="/chat">
                    <MessageCircle className="h-4 w-4 mr-2" />
                    {t('payment.manageMessages')}
                  </LocalizedLink>
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Announcement Details */}
          {announcementDetails && (
            <Card>
              <CardHeader>
                <CardTitle>{t('payment.adDetails')}</CardTitle>
                <CardDescription>
                  {t('payment.adPromoted')}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <h3 className="font-medium text-foreground mb-2">
                    {announcementDetails.title}
                  </h3>
                  <p className="text-sm text-muted-foreground line-clamp-3">
                    {announcementDetails.description}
                  </p>
                </div>

                {announcementDetails.price && (
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium">{t('payment.priceLabel')}</span>
                    <span className="text-lg font-bold text-primary">
                      {announcementDetails.price} {announcementDetails.currency}
                    </span>
                  </div>
                )}

                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium">{t('payment.locationLabel')}</span>
                  <span className="text-sm">
                    {announcementDetails.location}, {announcementDetails.wilaya}
                  </span>
                </div>

                <div className="flex gap-2 flex-wrap">
                  {announcementDetails.is_featured && (
                    <Badge variant="default" className="bg-yellow-500">
                      {t('payment.featured.badge')}
                    </Badge>
                  )}
                  {announcementDetails.is_urgent && (
                    <Badge variant="destructive">
                      Urgent
                    </Badge>
                  )}
                  {announcementDetails.is_active && (
                    <Badge variant="outline" className="text-green-600 border-green-600">
                      Active
                    </Badge>
                  )}
                  {announcementDetails.type === 'premium' && (
                    <Badge variant="secondary">Premium</Badge>
                  )}
                </div>

                <Button 
                  asChild 
                  variant="outline" 
                  className="w-full"
                >
                  <LocalizedLink to={`/announcement/${announcementDetails.id}`}>
                    {t('payment.viewPublicAd')}
                  </LocalizedLink>
                </Button>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Next Steps */}
        <Card className="mt-8">
          <CardHeader>
            <CardTitle>{t('payment.nextSteps')}</CardTitle>
            <CardDescription>
              {t('payment.nextStepsDesc')}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="text-center p-4 rounded-lg bg-muted/50">
                <Eye className="h-8 w-8 mx-auto mb-2 text-primary" />
                <h4 className="font-medium mb-1">{t('payment.monitorViews')}</h4>
                <p className="text-sm text-muted-foreground">
                  {t('payment.monitorViewsDesc')}
                </p>
              </div>

              <div className="text-center p-4 rounded-lg bg-muted/50">
                <MessageCircle className="h-8 w-8 mx-auto mb-2 text-primary" />
                <h4 className="font-medium mb-1">{t('payment.respondQuickly')}</h4>
                <p className="text-sm text-muted-foreground">
                  {t('payment.respondQuicklyDesc')}
                </p>
              </div>

              <div className="text-center p-4 rounded-lg bg-muted/50">
                <Star className="h-8 w-8 mx-auto mb-2 text-primary" />
                <h4 className="font-medium mb-1">{t('payment.addPhotos')}</h4>
                <p className="text-sm text-muted-foreground">
                  {t('payment.addPhotosDesc')}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Footer Actions */}
        <div className="text-center mt-8">
          <Button 
            variant="outline" 
            onClick={() => navigate(getLocalizedPath('/'))}
            className="mr-4"
          >
            {t('payment.backHome')}
          </Button>

          <Button asChild>
            <LocalizedLink to="/deposer-annonce">
              {t('payment.createNewAd')}
            </LocalizedLink>
          </Button>
        </div>
      </div>
    </div>
  );
};

export default PaymentSuccessPage;

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { MapPin, Briefcase, User, Mail, Save, Loader2, Phone, Home } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { useNavigate } from 'react-router-dom';
import { useSafeI18nWithRouter } from "@/lib/i18n/i18nContextWithRouter";

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Form, FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ProfileAvatar } from '@/components/profile/ProfileAvatar';
import { useProfile } from '@/hooks/useProfile';
import { useAuth } from '@/contexts/useAuth';

const Profile = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { profile, loading, saving, updateProfile } = useProfile();
  const { t } = useSafeI18nWithRouter();
  const [isEditing, setIsEditing] = useState(false);

  // Sch├®ma de validation
  const profileSchema = z.object({
    // Champs immuables (affich├®s mais non modifiables)
    first_name: z.string().optional(),
    last_name: z.string().optional(),
    gender: z.enum(['homme', 'femme']).nullable().optional(),
    phone: z.string().optional(),
    
    // Champs modifiables
    display_name: z.string().min(2, t('profile.validation.nameMinLength')).optional(),
    date_of_birth: z.string().optional(),
    profession: z.string().max(100, t('profile.validation.professionMaxLength')).optional(),
    bio: z.string().max(500, t('profile.validation.bioMaxLength')).optional(),
    
    // Nouveaux champs de contact et localisation
    phone_secondary: z.string().optional(),
    phone_tertiary: z.string().optional(),
    address: z.string().optional(),
    commune: z.string().min(1, t('profile.validation.required')).optional(), // Marqu├® comme requis dans la demande (*)
    wilaya: z.string().min(1, t('profile.validation.required')).optional(),  // Marqu├® comme requis dans la demande (*)
  });

  type ProfileFormData = z.infer<typeof profileSchema>;

  // Helper function to safely convert gender string to expected enum or null
  const normalizeGender = (gender: string | null): "homme" | "femme" | null => {
    if (!gender) return null;
    const lower = gender.toLowerCase();
    
    // Gestion des diff├®rentes variantes possibles
    if (lower === 'homme' || lower === 'male' || lower === 'm') {
      return 'homme';
    }
    if (lower === 'femme' || lower === 'female' || lower === 'f') {
      return 'femme';
    }
    
    return null;
  };

  const form = useForm<ProfileFormData>({
    resolver: zodResolver(profileSchema),
    defaultValues: {
      display_name: '',
      first_name: '',
      last_name: '',
      gender: null,
      phone: '',
      date_of_birth: '',
      profession: '',
      bio: '',
      phone_secondary: '',
      phone_tertiary: '',
      address: '',
      commune: '',
      wilaya: '',
    },
  });

  // Mise ├á jour du formulaire quand le profil change
  React.useEffect(() => {
    if (profile) {
      form.reset({
        display_name: profile.display_name || '',
        first_name: profile.first_name || '',
        last_name: profile.last_name || '',
        gender: normalizeGender(profile.gender),
        phone: profile.phone || '',
        date_of_birth: profile.date_of_birth || '',
        profession: profile.profession || '',
        bio: profile.bio || '',
        phone_secondary: profile.phone_secondary || '',
        phone_tertiary: profile.phone_tertiary || '',
        address: profile.address || '',
        commune: profile.commune || '',
        wilaya: profile.wilaya || '',
      });
    }
  }, [profile, form]);

  const onSubmit = async (data: ProfileFormData) => {
    // Filtrage strict des champs immuables
    // On retire first_name, last_name, gender, phone de l'objet envoy├®
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { first_name, last_name, gender, phone, ...editableData } = data;
    
    // On envoie uniquement les champs autoris├®s ├á la modification
    const success = await updateProfile(editableData);
    if (success) {
      setIsEditing(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-background to-secondary/20 flex items-center justify-center">
        <div className="flex items-center gap-2">
          <Loader2 className="h-6 w-6 animate-spin" />
          <span>{t('profile.loading')}</span>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-background to-secondary/20">
      <div className="container max-w-4xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-4 mb-6">
            <Button 
              variant="ghost" 
              onClick={() => navigate('/dashboard')}
              className="text-muted-foreground hover:text-foreground"
            >
              ÔåÉ {t('navigation.backToDashboard')}
            </Button>
          </div>
          
          <div className="text-center md:text-left">
            <h1 className="text-3xl font-bold bg-gradient-to-r from-primary to-secondary bg-clip-text text-transparent mb-2">
              {t('profile.title')}
            </h1>
            <p className="text-muted-foreground">
              {t('profile.subtitle')}
            </p>
          </div>
        </div>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
            
            {/* 1. Photo et Identit├® Principale */}
            <Card className="border-0 shadow-lg bg-card/50 backdrop-blur">
              <CardHeader className="pb-4">
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle className="flex items-center gap-2 text-lg">
                      <User className="h-5 w-5 text-primary" />
                      {t('profile.profilePhoto')}
                    </CardTitle>
                    <CardDescription>
                      {t('profile.profilePhotoDesc')}
                    </CardDescription>
                  </div>
                  {!isEditing && (
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => setIsEditing(true)}
                    >
                      {t('profile.editProfile')}
                    </Button>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                <div className="flex flex-col md:flex-row items-center gap-6">
                  <ProfileAvatar size="xl" editable={isEditing} />
                  <div className="text-center md:text-left space-y-1">
                    <h3 className="text-lg font-semibold">
                      {profile?.display_name || `${profile?.first_name} ${profile?.last_name}`.trim()}
                    </h3>
                    {user?.email && (
                      <p className="text-muted-foreground flex items-center gap-1 justify-center md:justify-start">
                        <Mail className="h-4 w-4" />
                        {user.email}
                      </p>
                    )}
                    {profile?.phone && (
                      <p className="text-muted-foreground flex items-center gap-1 justify-center md:justify-start">
                        <Phone className="h-4 w-4" />
                        {profile.phone}
                      </p>
                    )}
                    {profile?.wilaya && (
                      <p className="text-muted-foreground flex items-center gap-1 justify-center md:justify-start">
                        <MapPin className="h-4 w-4" />
                        {profile.commune}, {profile.wilaya}
                      </p>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* 2. Informations Immuables (Lecture Seule) */}
            <Card className="border-0 shadow-lg bg-card/50 backdrop-blur opacity-90">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-base text-muted-foreground">
                  <User className="h-4 w-4" />
                  {t('profile.identityInfo')}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="first_name"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t('profile.firstName')}</FormLabel>
                        <FormControl>
                          <Input {...field} disabled={true} className="bg-muted" />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="last_name"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t('profile.lastName')}</FormLabel>
                        <FormControl>
                          <Input {...field} disabled={true} className="bg-muted" />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="gender"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t('profile.gender')}</FormLabel>
                        <Select value={field.value || ''} disabled={true}>
                          <FormControl>
                            <SelectTrigger className="bg-muted">
                              <SelectValue />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="homme">{t('profile.homme')}</SelectItem>
                            <SelectItem value="femme">{t('profile.femme')}</SelectItem>
                          </SelectContent>
                        </Select>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="phone"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t('profile.phone')} {t('profile.phonePrincipal')}</FormLabel>
                        <FormControl>
                          <Input {...field} disabled={true} className="bg-muted" />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                </div>
              </CardContent>
            </Card>

            {/* 3. Informations Modifiables */}
            {isEditing && (
              <>
                <Card className="border-0 shadow-lg bg-card/50 backdrop-blur">
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <Briefcase className="h-5 w-5 text-primary" />
                      Informations Publiques & Contact
                    </CardTitle>
                    <CardDescription>{t('profile.publicInfoDesc')}</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    
                    {/* Surnom & Date de naissance */}
                    <div className="grid md:grid-cols-2 gap-4">
                      <FormField
                        control={form.control}
                        name="display_name"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>{t('profile.displayName')} {t('profile.surnom')}</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder={t('profile.nicknamePlaceholderShort')} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name="date_of_birth"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>{t('profile.dateOfBirth')}</FormLabel>
                            <FormControl>
                              <Input type="date" {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>

                    {/* Profession */}
                    <FormField
                      control={form.control}
                      name="profession"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>{t('profile.profession')}</FormLabel>
                          <FormControl>
                            <Input {...field} placeholder={t('profile.professionPlaceholderShort')} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {/* T├®l├®phones Secondaires */}
                    <div className="grid md:grid-cols-2 gap-4">
                      <FormField
                        control={form.control}
                        name="phone_secondary"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>{t('profile.phoneSecondaryLabel')}</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder="+213..." />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name="phone_tertiary"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>{t('profile.phoneTertiaryLabel')}</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder="+213..." />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>

                    {/* Localisation Compl├¿te */}
                    <div className="space-y-4 pt-4 border-t">
                      <h4 className="font-medium flex items-center gap-2">
                        <MapPin className="h-4 w-4" /> {t('profile.location')}
                      </h4>
                      <div className="grid md:grid-cols-2 gap-4">
                        <FormField
                          control={form.control}
                          name="wilaya"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Wilaya <span className="text-destructive">*</span></FormLabel>
                              <FormControl>
                                <Input {...field} placeholder={t('profile.wilayaPlaceholderShort')} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="commune"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Commune <span className="text-destructive">*</span></FormLabel>
                              <FormControl>
                                <Input {...field} placeholder={t('profile.communePlaceholderShort')} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                      <FormField
                        control={form.control}
                        name="address"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>{t('profile.addressLabel')}</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder={t('profile.addressPlaceholderShort')} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>

                    {/* Bio */}
                    <FormField
                      control={form.control}
                      name="bio"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>{t('profile.bio')}</FormLabel>
                          <FormControl>
                            <Textarea 
                              {...field} 
                              placeholder={t('profile.bioPlaceholderShort')} 
                              rows={4}
                              className="resize-none"
                            />
                          </FormControl>
                          <FormDescription>
                            {field.value?.length || 0}/500 {t('profile.characters')}
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </CardContent>
                  
                  <CardContent className="pt-6 border-t flex justify-end gap-3">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        setIsEditing(false);
                        form.reset();
                      }}
                      disabled={saving}
                    >
                      {t('profile.cancel')}
                    </Button>
                    <Button
                      type="submit"
                      disabled={saving || !form.formState.isDirty}
                    >
                      {saving ? (
                        <>
                          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                          {t('profile.saving')}
                        </>
                      ) : (
                        <>
                          <Save className="mr-2 h-4 w-4" />
                          {t('profile.save')}
                        </>
                      )}
                    </Button>
