const ShopDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { toast } = useToast();
  const { getLocalizedPath } = useLanguageNavigation();
  const { t, language } = useSafeI18nWithRouter();
  const { user } = useAuth();
  const location = useLocation();

  const [shop, setShop] = useState<Shop | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFavorite, setIsFavorite] = useState(false);
  const [showContactModal, setShowContactModal] = useState(false);
  const [isOwnerOnline, setIsOwnerOnline] = useState(false);

  const handleMessageClick = () => {
    if (!user) {
      window.dispatchEvent(new CustomEvent('open-auth-drawer', { detail: 'login' }));
      return;
    }
    setShowContactModal(true);
  };

  const handleReviewClick = () => {
    if (!user) {
      sessionStorage.setItem('authRedirectUrl', location.pathname + location.search);
      sessionStorage.setItem('openReviewModalAfterLogin', 'true');
      window.dispatchEvent(new CustomEvent('open-auth-drawer', { detail: 'login' }));
      return;
    }
    setShowReviewModal(true);
  };

  const [showReviewModal, setShowReviewModal] = useState(false);

  // Ouvrir automatiquement la modale d'avis apr├¿s une connexion r├®ussie
  useEffect(() => {
    if (user && sessionStorage.getItem('openReviewModalAfterLogin') === 'true') {
      sessionStorage.removeItem('openReviewModalAfterLogin');
      // Petit d├®lai pour laisser le temps au drawer de se fermer
      setTimeout(() => {
        setShowReviewModal(true);
      }, 500);
    }
  }, [user]);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reviews, setReviews] = useState<any[]>([]);
  const [reportReason, setReportReason] = useState('');
  const [reportDetails, setReportDetails] = useState('');
  const [reportSubmitting, setReportSubmitting] = useState(false);
  const currentUserReview = user ? reviews.find((review) => review.user_id === user.id) ?? null : null;

  const fetchShopReviews = async (shopId: string) => {
    const { data: reviewsData, error: reviewsError } = await supabase
      .from('shop_reviews')
      .select('id, rating, comment, created_at, user_id')
      .eq('shop_id', shopId)
      .order('created_at', { ascending: false });

    if (reviewsError) {
      throw reviewsError;
    }

    const userIds = Array.from(
      new Set((reviewsData || []).map((review) => review.user_id).filter(Boolean))
    );

    let profilesMap = new Map<string, { full_name: string | null; avatar_url: string | null }>();

    if (userIds.length > 0) {
      const { data: profilesData, error: profilesError } = await supabase
        .from('profiles_public')
        .select('user_id, full_name, avatar_url')
        .in('user_id', userIds);

      if (profilesError) {
        throw profilesError;
      }

      profilesMap = new Map(
        (profilesData || []).map((profile) => [
          profile.user_id as string,
          {
            full_name: (profile as { full_name?: string | null }).full_name ?? null,
            avatar_url: (profile as { avatar_url?: string | null }).avatar_url ?? null,
          },
        ])
      );
    }

    const normalizedReviews = (reviewsData || []).map((review) => ({
      ...review,
      profiles: profilesMap.get(review.user_id) || null,
    }));

    setReviews(normalizedReviews);

    return normalizedReviews;
  };

  const getOrCreateReportSessionId = () => {
    const storageKey = 'report_session_id';
    const existing = localStorage.getItem(storageKey);
    if (existing && existing.length >= 10 && existing.length <= 100) return existing;
    const newId = generateSessionId();
    localStorage.setItem(storageKey, newId);
    return newId;
  };

  const submitReport = async () => {
    if (!shop) return;
    if (!reportReason) {
      toast({
        title: tr('viewShop.reportReasonRequired', { fr: 'Cause requise', en: 'Reason required', es: 'Motivo obligatorio', it: 'Motivo obbligatorio', de: 'Grund erforderlich', ar: 'Ïº┘äÏ│Ï¿Ï¿ ┘àÏÀ┘ä┘êÏ¿' }),
        description: tr('viewShop.reportReasonRequiredText', { fr: 'Veuillez s├®lectionner une cause de signalement.', en: 'Please select a report reason.', es: 'Por favor selecciona un motivo del reporte.', it: 'Seleziona un motivo della segnalazione.', de: 'Bitte w├ñhlen Sie einen Meldegrund aus.', ar: '┘èÏ▒Ï¼┘ë ÏºÏ«Ï¬┘èÏºÏ▒ Ï│Ï¿Ï¿ Ïº┘äÏÑÏ¿┘äÏºÏ║.' }),
        variant: "destructive"
      });
      return;
    }

    try {
      setReportSubmitting(true);

      const clientSessionId = getOrCreateReportSessionId();
      const payload = {
        reporter_user_id: user?.id ?? null,
        client_session_id: clientSessionId,
        target_type: 'shop',
        target_id: shop.id,
        target_global_number: shop.globalListingNumber ?? null,
        target_owner_user_id: shop.ownerId ?? null,
        target_title: shop.name ?? null,
        target_wilaya: shop.wilaya ?? null,
        reason: reportReason,
        details: reportDetails.trim() ? reportDetails.trim() : null
      };

      const { error } = await supabase.from('reports').insert(payload);
      if (error) throw error;

      toast({
        title: tr('viewShop.reportSent', { fr: 'Signalement envoy├®', en: 'Report sent', es: 'Reporte enviado', it: 'Segnalazione inviata', de: 'Meldung gesendet', ar: 'Ï¬┘à ÏÑÏ▒Ï│Ïº┘ä Ïº┘äÏ¿┘äÏºÏ║' }),
        description: tr('viewShop.reportSentText', { fr: 'Merci. Notre ├®quipe va examiner ce contenu.', en: 'Thank you. Our team will review this content.', es: 'Gracias. Nuestro equipo revisar├í este contenido.', it: 'Grazie. Il nostro team esaminer├á questo contenuto.', de: 'Vielen Dank. Unser Team wird diesen Inhalt pr├╝fen.', ar: 'Ï┤┘âÏ▒Ïº┘ï ┘ä┘â. Ï│┘è┘é┘ê┘à ┘üÏ▒┘è┘é┘åÏº Ï¿┘àÏ▒ÏºÏ¼Ï╣Ï® ┘çÏ░Ïº Ïº┘ä┘àÏ¡Ï¬┘ê┘ë.' }),
      });

      setShowReportModal(false);
      setReportReason('');
      setReportDetails('');
    } catch (error) {
      logger.error('Error submitting report:', error);
      toast({
        title: t('common.error'),
        description: tr('viewShop.reportError', { fr: "Impossible d'envoyer le signalement. Veuillez r├®essayer plus tard.", en: 'Unable to send the report. Please try again later.', es: 'No se pudo enviar el reporte. Int├®ntalo de nuevo m├ís tarde.', it: 'Impossibile inviare la segnalazione. Riprova pi├╣ tardi.', de: 'Die Meldung konnte nicht gesendet werden. Bitte versuchen Sie es sp├ñter erneut.', ar: 'Ï¬Ï╣Ï░Ï▒ ÏÑÏ▒Ï│Ïº┘ä Ïº┘äÏ¿┘äÏºÏ║. ┘èÏ▒Ï¼┘ë Ïº┘ä┘àÏ¡Ïº┘ê┘äÏ® ┘äÏºÏ¡┘éÏº┘ï.' }),
        variant: "destructive"
      });
    } finally {
      setReportSubmitting(false);
    }
  };

  // Effet pour charger les donn├®es de la boutique
  useEffect(() => {
    logger.debug("ShopDetails Page Loaded:", id);
    const fetchShop = async () => {
      try {
        setLoading(true);

        // R├®cup├®rer les donn├®es depuis Supabase
        const { data, error } = await supabase
          .from('shops')
          .select('*')
          .eq('id', id)
          .single();

        if (error) throw error;

        if (data) {
          // Adapter les noms de champs de la base de donn├®es ├á l'interface du composant
          const adaptedShop: Shop = {
            id: data.id,
            ownerId: data.user_id,
            globalListingNumber: data.global_listing_number ?? undefined,
            name: data.name,
            description: data.description,
            wilaya: data.wilaya,
            commune: data.commune,
            phoneNumbers: data.phone_numbers || [],
            landlinePhone: data.landline_phone,
            logoUrl: data.logo_url,
            bannerUrl: data.banner_url,
            productImageUrls: data.product_image_urls || [],
            productVideoUrls: data.product_video_urls || [],
            isOnline: data.is_online,
            isPhysical: data.is_physical,
            isVerified: data.is_verified,
            shopStatus: data.shop_status,
            shop_number: data.shop_number,
            address: data.address,
            website: data.website,
            whatsappNumber: data.whatsapp_number,
            mainCategory: data.main_category,
            socialMedia: (data.social_media as ShopSocialMedia | null) ?? undefined,
            openingHours: (data.opening_hours as ShopOpeningHours | null) ?? undefined,
            deliveryOptions: (data.delivery_options as string[] | null) ?? undefined,
            paymentMethods: (data.payment_methods as string[] | null) ?? undefined,
            rating: data.rating || 0, // Utiliser la vraie note ou 0
            reviewCount: data.review_count || 0, // Utiliser le vrai count ou 0
            followerCount: data.view_count || 0,
            gpsCoordinates: data.gps_coordinates as { lat: number; lng: number } || { lat: 36.75, lng: 3.06 }
          };
          setShop(adaptedShop);

          await fetchShopReviews(id);

          const viewKey = `viewed_shop_${id}`;
          if (!sessionStorage.getItem(viewKey)) {
            sessionStorage.setItem(viewKey, '1');
            try {
              await supabase.rpc('increment_shop_view_count', { shop_uuid: id });
              setShop((prev) =>
                prev
                  ? {
                      ...prev,
                      followerCount: (prev.followerCount ?? 0) + 1,
                    }
                  : prev
              );
            } catch (err) {
              logger.error('Error incrementing shop view count:', err);
            }
