        toast({
          title: t('common.error'),
          description: tr('shop.messages.errorLoadingShop', { fr: 'Impossible de charger les informations de la boutique', en: 'Unable to load shop information', es: 'No se pudo cargar la informaci├│n de la tienda', it: 'Impossibile caricare le informazioni del negozio', de: 'Shop-Informationen konnten nicht geladen werden', ar: 'Ï¬Ï╣Ï░Ï▒ Ï¬Ï¡┘à┘è┘ä ┘àÏ╣┘ä┘ê┘àÏºÏ¬ Ïº┘ä┘àÏ¬Ï¼Ï▒' }),
