                variant="outline"
                onClick={() => setShowReportModal(false)}
                disabled={reportSubmitting}
              >
                {tr('common.cancel', { fr: 'Annuler', en: 'Cancel', es: 'Cancelar', it: 'Annulla', de: 'Abbrechen', ar: 'ÏÑ┘äÏ║ÏºÏí' })}
              </Button>
              <Button onClick={submitReport} disabled={reportSubmitting}>
                {reportSubmitting ? tr('viewShop.sending', { fr: 'Envoi...', en: 'Sending...', es: 'Enviando...', it: 'Invio...', de: 'Senden...', ar: 'Ï¼ÏºÏ▒┘ì Ïº┘äÏÑÏ▒Ï│Ïº┘ä...' }) : tr('common.send', { fr: 'Envoyer', en: 'Send', es: 'Enviar', it: 'Invia', de: 'Senden', ar: 'ÏÑÏ▒Ï│Ïº┘ä' })}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal de contact */}
      {showContactModal && (
        <ContactModal
          shop={shop}
          onClose={() => setShowContactModal(false)}
        />
      )}
      {showReviewModal && shop && (
        <ShopReviewModal
          isOpen={showReviewModal}
          onClose={() => setShowReviewModal(false)}
          shopId={shop.id}
          shopName={shop.name}
          existingReview={currentUserReview}
          onReviewSubmitted={async () => {
            const data = await fetchShopReviews(shop.id);
            const avg = data.length > 0
              ? data.reduce((acc, curr) => acc + curr.rating, 0) / data.length
              : 0;
            setShop(prev => prev ? { ...prev, rating: avg, reviewCount: data.length } : null);
          }}
        />
      )}
    </div>
  );
};

